// Üretilen dosya: tool/ozgun/uret.py. Sanat · Fotoğraf sanatı ve fotoğraf tarihi (orta).
const ozArt10Orta = <(String, String, List<String>, String)>[
  ('Alman bilgin Johann Heinrich Schulze\'nin 1720\'lerde yaptığı deneyler fotoğrafın ön tarihine hangi bulguyu kazandırmıştır?', 'Gümüş tuzlarını ışığın kararttığını', ['Camın beyaz ışığı renklerine ayırdığını', 'Doğal asfaltın güneşte yumuşadığını', 'İnce kenarlı merceklerin görüntüyü küçülttüğünü'], 'Schulze, gümüş tuzu içeren karışımın kararmasına ışığın yol açtığını göstermiş ve ışığa duyarlı kimyasalların yolunu açmıştır.'),
  ('1800\'lerin başında Thomas Wedgwood\'un gümüş nitrat sürülmüş deri ve kâğıt üzerinde elde ettiği silüet görüntüler neden kalıcı olamamıştır?', 'Sabitleme yöntemi bilinmediği için', ['Kullandığı kâğıt nemden çabucak çürüdüğü için', 'Gümüş nitrat ışıkta hiç tepki vermediği için', 'Görüntüler yalnız ay ışığında oluştuğu için'], 'Işık görmemiş gümüş tuzları ortamdan uzaklaştırılamadığından görüntüler ışığa çıkarılınca tümüyle kararıyordu; bu yüzden ancak loş ışıkta kısa süre izlenebiliyorlardı.'),
  ('Niépce\'nin Le Gras\'taki pencereden çektiği görüntüde avludaki binaların karşılıklı iki cephesinin de güneş alıyormuş gibi görünmesi en iyi nasıl açıklanır?', 'Güneşin uzun pozlama boyunca gökte yer değiştirmesi', ['Niépce iki ayrı levhayı üst üste yapıştırarak birleştirmiştir', 'Bitüm yansıyan ay ışığını da kaydetmiştir', 'Görüntü sonradan elle boyanarak aydınlatılmıştır'], 'Çok uzun pozlama boyunca güneş doğudan batıya ilerlediğinden binaların her iki yüzü de farklı saatlerde aydınlanıp aynı karede aydınlık görünmüştür.'),
  ('Louis Daguerre, 1829\'da Niépce ile ortaklık kurmadan önce Paris\'te hangi alandaki çalışmalarıyla tanınıyordu?', 'Işık etkili dev Diorama gösterileri', ['Saray için yaptığı mermer büstler', 'Gazetelere çizdiği siyasi karikatürler', 'Sevr porselen fabrikasındaki süsleme işleri'], 'Daguerre bir tiyatro dekor ressamıydı; aydınlatmayla gündüzden geceye dönüşen büyük resimlerin sergilendiği Diorama gösterileriyle ün kazanmıştı.'),
  ('Bir koleksiyoncu elindeki dagerreyotipi eğdiğinde görüntünün bir anda negatife dönüştüğünü görüyor. Bunun nedeni nedir?', 'Parlak gümüşün karanlık bir yüzeyi yansıtması', ['Cıva tanelerinin ışıkta renk değiştirmesi', 'Levhanın arkasındaki negatifin camdan görünmesi', 'Görüntünün iki ayrı katmana basılmış olması'], 'Görüntünün açık tonları cıva-gümüş taneciklerinden, koyu tonları ise parlak gümüşün yansıttığı karanlıktan oluşur; yansıyan şey aydınlık olunca tonlar tersine döner.'),
  ('Fransız devletinin 1839\'da Daguerre\'e ömür boyu maaş bağlayarak dagerreyotipi satın almasının en önemli sonucu ne olmuştur?', 'Yöntemin Fransa\'da herkesin serbestçe kullanımına açılması', ['Fotoğraf çekme hakkının yalnızca devlet görevlilerine bırakılması', 'Dagerreyotip levhalarının ihracatının yasaklanması', 'Fotoğrafçıların akademiye kayıt zorunluluğu getirilmesi'], 'Devlet buluşu "dünyaya armağan" ettiğini duyurdu; ancak Daguerre İngiltere\'de ayrıca patent aldığından orada kullanım lisansa bağlı kaldı.'),
  ('Daguerre\'in 1838\'de Paris\'te çektiği Boulevard du Temple görüntüsü fotoğraf tarihinde neden özel bir yer tutar?', 'İnsan içeren bilinen en eski fotoğraflardan olması', ['Renkli olarak çekilmiş ilk sokak görüntüsü olması', 'Bir Paris gazetesinde basılan ilk fotoğraf olma özelliği', 'Gece çekilmiş ilk kent fotoğrafı olması'], 'Uzun pozlama yüzünden yoldan geçenler görünmez; ancak ayakkabısını boyatırken kıpırdamadan duran bir adam kareye kaydedilmiş ve fotoğraflanan ilk insanlardan biri olmuştur.'),
  ('Brezilya\'da yaşayan Fransız ressam Hercule Florence fotoğraf tarihinde neden anılır?', 'Erken ve bağımsız bir yöntem bulup "photographie" demesi', ['Güney Amerika\'daki ilk fotoğraf dergisini kurduğu için', 'Amazon ormanlarını dagerreyotiple belgeleyen ilk Avrupalı olduğu için', 'Renkli film banyosunun formülünü bulduğu için'], 'Florence, Avrupa\'dan habersiz biçimde gümüş tuzlarıyla görüntü elde etmiş ve defterlerinde "photographie" sözcüğünü erkenden kullanmıştır.'),
  ('Fotoğrafçılıkta "negatif" ve "pozitif" terimlerini yaygınlaştıran, ayrıca sodyum tiyosülfatın gümüş tuzlarını çözdüğünü bularak sabitleme sorununu çözen İngiliz bilgin kimdir?', 'John Herschel', ['Michael Faraday', 'David Brewster', 'Humphry Davy'], 'Gökbilimci John Herschel, 1819\'daki bulgusunu 1839\'da sabitleyici olarak önermiş ve fotoğraf dilinin temel terimlerini yerleştirmiştir.'),
  ('Demir tuzlarına dayanan ve mavi tonlu görüntüler veren siyanotip yöntemini 1842\'de bulan bilgin kimdir?', 'John Herschel', ['Anna Atkins', 'Alphonse Poitevin', 'Robert Hunt'], 'Siyanotipi Herschel bulmuş; Anna Atkins bu yöntemi kısa süre sonra deniz yosunlarını görüntülemek için kullanmıştır.'),
  ('Talbot\'un 1835\'te çektiği ve günümüze ulaşan en eski kamera negatifi sayılan küçük görüntüde ne yer alır?', 'Lacock Abbey\'deki cumbalı bir pencere', ['Westminster Sarayı\'nın saat kulesi', 'Oxford\'daki bir kolejin taş döşeli avlusu', 'Thames üzerindeki bir köprü'], 'Talbot, Lacock Abbey\'deki evinin kafesli cumba penceresini fotoğraflamış; birkaç santimlik bu negatif, kâğıt negatif geleneğinin ilk örneğidir.'),
  ('Talbot\'un 1844-1846 yıllarında fasiküller hâlinde yayımladığı ve fotoğrafın olası kullanımlarını örnek baskılar ve yorumlarla anlatan yapıtın adı nedir?', 'Doğanın Kalemi (The Pencil of Nature)', ['Işığın Kitabı (The Book of Light)', 'Güneşle Çizilen Resimler (Sun Pictures)', 'Kimyasal Çizimler (Chemical Drawings)'], 'The Pencil of Nature, fotoğraf baskılarıyla resimlenip ticari olarak satışa sunulan ilk kitaplardandır.'),
  ('Talbot\'un 1840\'ta bulduğu, kısa bir pozlamadan sonra görünmeyen "gizli görüntü"nün kimyasal olarak geliştirilmesi ilkesi fotoğrafçılığa en çok ne kazandırmıştır?', 'Pozlama süresinin büyük ölçüde kısalmasını', ['Görüntünün ilk kez renkli olarak kaydedilebilmesini', 'Negatifin camdan yapılmasını', 'Baskıların hiç solmamasını'], 'Görüntü kamerada tamamlanana dek beklemek yerine kısa pozlamayla oluşan gizli görüntü sonradan güçlendirildiği için pozlama dakikalardan saniyelere doğru inebilmiştir.'),
  ('1840\'larda Edinburgh\'da kalotip yöntemiyle Newhaven\'lı balıkçı kadınlarını ve İskoç Kilisesi papazlarını fotoğraflayan ünlü ikili kimdir?', 'David Octavius Hill ve Robert Adamson', ['Albert Southworth ve Josiah Hawes', 'Auguste ve Louis Lumière', 'Louis-Auguste ve Auguste-Rosalie Bisson'], 'Ressam Hill ile kimyager-fotoğrafçı Adamson\'ın ortak çalışmaları, kalotipin yumuşak tonlarını portre ve belgeselde ustalıkla kullanmalarıyla bilinir.'),
  ('Islak kolodyon yöntemini 1851\'de yayımlayan ve buluşu için patent almayarak hızla yaygınlaşmasını sağlayan İngiliz heykeltıraş kimdir?', 'Frederick Scott Archer', ['Richard Leach Maddox', 'Joseph Swan', 'Gustave Le Gray'], 'Archer\'ın yöntemini patentsiz bırakması, cam negatifli kolodyonun 1850\'lerde kısa sürede dünyanın her yerinde benimsenmesine yardım etmiştir.'),
  ('Islak kolodyonun 1850\'lerde hem dagerreyotipin hem de kalotipin yerini hızla almasının temel nedeni nedir?', 'Keskin ayrıntıyı çoğaltılabilir negatifle birleştirmesi', ['Yöntemin hiçbir kimyasal gerektirmemesi', 'Renkli görüntüyü ilk kez mümkün kılması', 'Levhaların haftalar öncesinden hazırlanıp saklanabilmesi'], 'Cam üzerindeki kolodyon negatif hem çok ince ayrıntı veriyor hem de istenildiği kadar kâğıt baskı alınmasına olanak tanıyordu.'),
  ('Adında "teneke" anlamı bulunmasına karşın aslında siyaha boyanmış ince demir levha üzerine yapılan, ucuzluğu ve dayanıklılığıyla ABD İç Savaşı askerleri arasında yaygınlaşan doğrudan pozitif türü hangisidir?', 'Tintip (ferrotip)', ['Ambrotip', 'Kalotip', 'Siyanotip (mavi baskı yöntemi)'], 'Tintip, kolodyonun koyu lakeli demir levhaya sürülmesiyle yapılır; kırılmadığı için mektupla gönderilebilir ve fuarlarda dakikalar içinde teslim edilebilirdi.'),
  ('Bir arşivde 1870\'lerden kalma albümin baskıların büyük bölümünün sarımsı ve soluk görünmesinin en olası nedeni nedir?', 'Albümin katmanının ve ince gümüş taneciklerinin zamanla bozunması', ['Baskıların başlangıçta sepya mürekkeple basılmış olması ve kâğıtların yağlı ellerle tutulması', 'Fotoğrafçıların bilerek sarı filtre kullanması', 'Kartonların renginin görüntüye geçmesi'], 'Albümin baskıdaki ince gümüş tanecikleri ışık, nem ve hava kirliliğiyle kolayca bozunur; protein katmanı da yaşlandıkça sararır.'),
  ('1854\'te patentini aldığı yöntemle çok mercekli bir kamerayla tek cam levhada birden çok küçük portre çekip bunları kartlara yapıştıran ve portreyi ucuzlatan Parisli fotoğrafçı kimdir?', 'André-Adolphe-Eugène Disdéri', ['Étienne Carjat', 'Antoine Claudet', 'Gustave Le Gray'], 'Disdéri\'nin "carte de visite" (kartvizit portre) yöntemi, birden çok pozu tek levhaya sığdırarak maliyeti düşürmüş ve portreyi orta sınıfa ulaştırmıştır.'),
  ('İki göz arasındaki görüş farkının derinlik algısını sağladığını 1838\'de aynalı bir stereoskopla gösteren İngiliz bilgin kimdir?', 'Charles Wheatstone', ['David Brewster', 'James Clerk Maxwell', 'John Herschel'], 'Wheatstone stereoskobu fotoğraftan önce çizimlerle tanıtmış; Brewster daha sonra mercekli, taşınabilir bir model geliştirmiştir.'),
  ('Amerikalı yazar ve hekim Oliver Wendell Holmes fotoğraf tarihinde neden anılır?', 'Patentsiz ve ucuz bir el stereoskobu tasarladığı için', ['Ameliyatları fotoğraflayan ilk hekim olduğu için', 'Röntgen filmini geliştiren ekibi yönettiği için', 'ABD\'de fotoğrafçıları koruyan ilk telif yasasının taslağını hazırladığı için'], 'Holmes 1861\'de basit ve ucuz bir el stereoskobu tasarlamış, bilerek patent almadığından aygıt milyonlarca evde stereo kart izlemek için kullanılmıştır.'),
  ('Kendini "Nadar" takma adıyla tanıtan ünlü Fransız portre fotoğrafçısının asıl adı nedir?', 'Gaspard-Félix Tournachon', ['Étienne Carjat', 'Hippolyte Bayard', 'Charles Nègre'], 'Karikatürist olarak başlayan Tournachon, Nadar adıyla Baudelaire, Sarah Bernhardt ve Hugo gibi dönemin ünlülerinin sade, karakter odaklı portrelerini çekmiştir.'),
  ('Nadar\'ın 1860\'ların başında Paris\'in yeraltı mezarlıkları ve kanalizasyonlarında yaptığı çekimler neden öncü sayılır?', 'Yapay ışıkla yapılmış ilk kapsamlı çalışmalardan oldukları için', ['Kentin ilk renkli fotoğrafları oldukları için', 'İlk kez ıslak kolodyon kullanılarak çekildikleri için', 'Bir dergide dizi olarak yayımlanan ilk fotoğraflar oldukları için'], 'Nadar pil ile beslenen elektrik ışığı kullanmış; uzun pozlama sırasında işçileri canlandırmak için yer yer mankenlerden yararlanmıştır.'),
  ('Gustave Le Gray 1850\'lerdeki deniz manzaralarında gökyüzündeki bulutlar ile karanlık denizi aynı karede ayrıntılı göstermeyi çoğu kez nasıl başarmıştır?', 'Ayrı pozlanmış iki negatifi tek baskıda birleştirerek', ['Objektifin önüne kırmızı bir cam koyarak', 'Gece ay ışığında çok uzun pozlama yaparak ve filmi sonradan boyayarak', 'Denizi baskı üzerinde elle boyayarak'], 'Gökyüzü ve deniz için ayrı negatifler kullanan Le Gray, tek pozlamada imkânsız olan ton dengesini baskı aşamasında kurmuştur.'),
  ('1871\'de gümüş bromürü kolodyon yerine jelatin içinde askıya alma fikrini yayımlayarak kuru levhanın yolunu açan İngiliz hekim kimdir?', 'Richard Leach Maddox', ['Frederick Scott Archer', 'Charles Bennett', 'Joseph Swan'], 'Maddox\'un önerisini başkaları geliştirmiş; 1870\'lerin sonunda fabrikada üretilen, duyarlılığı yüksek jelatin kuru levhalar piyasaya çıkmıştır.'),
  ('Fabrikada üretilen jelatin kuru levhaların 1880\'lerde yaygınlaşması dışarıda çalışan fotoğrafçıların işini en çok nasıl değiştirmiştir?', 'Çekim yerine taşınabilir karanlık oda götürme zorunluluğunu kaldırmıştır', ['Fotoğrafları ilk kez renkli kılmıştır', 'Tripotu tamamen gereksiz kılmıştır', 'Baskı almayı olanaksız hâle getirmiştir'], 'Islak kolodyon levhası çekimden hemen önce hazırlanıp hemen banyo edilmek zorundaydı; kuru levha ise aylar önce alınıp çekimden sonra evde işlenebiliyordu.'),
  ('George Eastman\'ın "Kodak" adını seçerken gözettiği ölçüt aşağıdakilerden hangisidir?', 'Kısa, her dilde aynı okunan, anlamsız ve K ile başlayıp biten bir sözcük olması', ['Annesinin kızlık soyadından türetilmiş olması', 'Yunanca "ışık kutusu" anlamına gelmesi', 'Şirketin kurucu ortaklarının adlarının ve soyadlarının baş harflerinden oluşturulmuş olması'], 'Eastman güçlü ve keskin bulduğu K harfini seviyordu; uydurduğu ad her dilde aynı biçimde söylenebilecek, anlamsız bir sözcüktü.'),
  ('Eastman\'ın 1889\'da kâğıt taşıyıcı yerine kullanmaya başladığı saydam ve esnek film tabanı hangi malzemedendi?', 'Nitroselüloz', ['Selüloz asetat', 'Polyester', 'İnce cam'], 'Saydam nitroselüloz taban hem fotoğraf hem sinema filmini olanaklı kılmış; ancak kolay tutuştuğu için sonraları asetat tabanla değiştirilmiştir.'),
  ('1925\'te piyasaya çıkan Leica\'nın tasarımcısı Oskar Barnack\'ın küçük fotoğraf makinesi için temel fikri neydi?', 'Sinemada kullanılan 35 mm delikli filmi fotoğraf için kullanmak', ['Cam levhaları ikiye bölerek iki poz almak', 'Rulo kâğıt negatife geri dönmek', 'Makinenin içine banyo düzeneği yerleştirmek ve bunu yasal bir zorunluluk olarak'], 'Barnack sinema filmini yatayda çift kare boyutunda (24 × 36 mm) pozlayarak taşınabilir, çok pozlu bir makine tasarlamıştır.'),
  ('Küçük ve sessiz 35 mm makinelerin 1930\'larda yaygınlaşması foto muhabirliğini en çok nasıl etkilemiştir?', 'Fotoğrafçıların olayların içinde fark edilmeden anlık ve doğal kareler yakalamasını sağlamıştır', ['Fotoğrafçıların yalnız stüdyoda çalışmasını zorunlu kılmıştır', 'Haber fotoğraflarının renkli basılmasını başlatmıştır', 'Haber fotoğraflarının gazetelere telgraf hattıyla gönderilmesi uygulamasını tamamen sona erdirmiştir'], 'Hafif makineler ve çok pozlu film, poz verdirmeden, hareket hâlindeki yaşamı kaydetmeyi mümkün kılmış; "belirleyici an" anlayışının teknik zeminini hazırlamıştır.'),
  ('1920\'lerin sonunda geniş diyaframlı küçük bir makineyle diplomatik toplantıları ve mahkeme salonlarını habersizce fotoğraflayan, "candid" fotoğrafın öncüsü sayılan Alman kimdir?', 'Erich Salomon', ['August Sander', 'Albert Renger-Patzsch', 'Felix H. Man'], 'Salomon, loş iç mekânlarda flaşsız çekim yaparak siyasetçileri poz vermedikleri doğal anlarda göstermiştir.'),
  ('Apollo programında Ay yüzeyinde fotoğraf çekmek için kullanılan İsveç yapımı orta format makinelerin markası hangisidir?', 'Hasselblad', ['Leica', 'Rolleiflex', 'Mamiya'], 'NASA\'nın özel olarak uyarladığı Hasselblad makineleri Ay yüzeyindeki ünlü fotoğrafların çoğunu kaydetmiştir.'),
  ('Polaroid\'in 1972\'de tanıttığı SX-70 sistemini önceki anında fotoğraf filmlerinden ayıran yenilik nedir?', 'Atılacak negatif kalmadan görüntünün kartın içinde belirmesi', ['Anında fotoğrafta görüntünün ilk kez renkli olarak çıkabilmesi', 'Fotoğrafların ancak karanlıkta çıkarılabilmesi', 'Her pozun ayrı bir cam levhaya kaydedilmesi'], 'SX-70\'in "bütünleşik" filmi, makineden çıkan kartın içinde tüm kimyasal süreci tamamlıyor, kullanıcıya atık bırakmıyordu.'),
  ('Lucas Samaras\'ın 1970\'lerdeki "Fotodönüşümler" adlı Polaroid çalışmalarında kullandığı tipik müdahale nedir?', 'Oluşan görüntünün yumuşak emülsiyonunu bastırıp sürüklemek', ['Baskıları mum alevinde yakıp kenarlarını kömürleştirerek eskitmek', 'Fotoğrafları şeritlere kesip örgü gibi dokumak', 'Kartları güneşte haftalarca soldurmak'], 'SX-70 filmindeki boya katmanları birkaç dakika yumuşak kaldığından Samaras yüzeye bastırarak kendi bedenini düşsel, bozulmuş görüntülere dönüştürmüştür.'),
  ('Kodak\'ın 1963\'te tanıttığı Instamatic makinelerin sıradan kullanıcıya sağladığı başlıca kolaylık nedir?', 'Filmin elle sarılmadan takılıp çıkarılan bir kartuşla yüklenmesi', ['Fotoğrafların makineden basılı olarak çıkması ve sadece çok sayıda poz içermesi', 'Görüntülerin bir bellek kartına kaydedilmesi', 'Objektifin otomatik olarak değiştirilmesi'], 'Instamatic\'in 126 kartuşu, film yükleme sırasındaki hataları ve ışık sızmasını büyük ölçüde ortadan kaldırmıştır.'),
  ('Dijital fotoğraf makinesini ilk geliştiren şirketlerden biri olmasına karşın Kodak\'ın 2012\'de iflas koruması başvurusu yapması en çok neyle açıklanır?', 'Kârlı film satışlarına bağlı iş modelinde direnmesiyle', ['Şirketin hiç dijital ürün geliştirmemesiyle', 'Film üretiminin yasalarla yasaklanmasıyla', 'Rakip Japon firmalarının bütün dijital patentlerini satın almasıyla'], 'Kodak dijital teknolojiyi erken tanısa da film ve kimyasal satışlarını korumaya öncelik verdi; pazar dijitale kayınca gelir kaynağı çöktü.'),
  ('1861\'de Londra\'da bir ekose kurdeleyi kırmızı, yeşil ve mavi filtrelerle üç kez fotoğraflatıp görüntüleri üst üste yansıtarak üç renk ilkesini gösteren fizikçi kimdir?', 'James Clerk Maxwell', ['Michael Faraday', 'William Thomson', 'Thomas Young'], 'Maxwell\'in Royal Institution\'daki gösterisi, üç renk ayrımına dayanan renkli fotoğrafın ilk örneği sayılır; çekimleri Thomas Sutton yapmıştır.'),
  ('Maxwell\'in 1861\'deki üç renk gösterisinin başarısı sonradan neden kısmen şansa bağlanmıştır?', 'Kırmızı kayıt, kumaşın morötesi yansımasıyla oluştuğu için', ['Kurdele aslında yalnız siyah ve beyaz renklerden oluştuğu için', 'Gösteri sırasında salonun ışıkları yanlışlıkla açık kaldığı için', 'Üç görüntüden ikisi aynı filtreyle çekildiği için'], 'Dönemin kolodyonu kırmızı ışığı neredeyse hiç kaydetmiyordu; kırmızı filtreli kare, kırmızı boyaların yansıttığı morötesi ışık sayesinde görüntü vermiştir.'),
  ('1868\'de çıkarmalı renk yöntemlerinin ilkelerini ortaya koyarak renkli fotoğrafın kuramsal temellerini atan Fransız mucit kimdir?', 'Louis Ducos du Hauron', ['Gabriel Lippmann', 'Louis Lumière', 'Jean-Baptiste Sabattier'], 'Ducos du Hauron, üç renk ayrımını camgöbeği, eflatun ve sarı pigmentlerle birleştiren yöntemler önermiş ve 1870\'lerde renkli manzara baskıları elde etmiştir.'),
  ('Lumière kardeşlerin 1907\'de piyasaya sürdüğü Autochrome levhalarında renk filtresi işlevi gören minik taneler neydi?', 'Boyanmış patates nişastası taneleri', ['Öğütülmüş renkli cam tozları', 'Gümüş ve bakır karışımı tozlar', 'Boyayla renklendirilmiş pirinç unu kristalleri'], 'Turuncu, yeşil ve mor-mavi boyanan nişasta taneleri cam levhaya serilir, aradaki boşluklar karbon tozuyla doldurulurdu; her tane küçük bir renk filtresi gibi çalışırdı.'),
  ('Autochrome görüntülere yakından bakıldığında Puantilist resimleri andıran noktalı bir doku görülmesinin nedeni nedir?', 'Rengin renkli taneciklerin gözde karışmasıyla oluşması', ['Görüntünün matbaada raster noktalarla basılması', 'Levhaların fırçayla nokta nokta boyanması', 'Fotoğrafçıların bilerek bulanık objektif kullanması ve bunun için özel merceklerin kullanılması'], 'Autochrome\'da her renk, milyonlarca küçük renkli filtrenin bir araya gelmesiyle oluşur; bu optik karışım Seurat\'nın noktacı tekniğine benzer bir yüzey verir.'),
  ('Prokudin-Gorsky\'nin renkli birleştirmelerinde akan su ya da yürüyen insanların kenarlarında kırmızı, yeşil ve mavi saçaklar görülmesinin nedeni nedir?', 'Art arda çekilen üç pozda hareketli öğelerin örtüşmemesi', ['Objektifin farklı dalga boylarını farklı noktalarda toplaması', 'Cam negatiflerin zamanla çatlayıp kayması', 'Arşivcilerin görüntüleri elle renklendirmesi'], 'Üç pozlama arasında geçen kısa sürede hareket eden nesneler yer değiştirdiğinden birleştirilmiş görüntüde renkli "hayalet" kenarlar oluşur.'),
  ('Bir gezgin fotoğrafçı, ışığı değişken ve kontrastı yüksek sahnelerde pozlama hatalarına karşı en hoşgörülü filmi seçmek istiyor. Hangisi en uygundur?', 'Renkli negatif film', ['Renkli slayt filmi', 'Ortokromatik cam levha', 'Kızılötesi film'], 'Renkli negatif film özellikle fazla pozlamaya karşı geniş bir tolerans tanır; slayt filmi ise yarım duraklık hatayı bile belli eder.'),
  ('1890\'larda İsviçre\'de geliştirilen, siyah beyaz bir negatiften birçok litografi taşı kullanarak renkli turistik manzara baskıları üreten yöntem hangisidir?', 'Fotokrom', ['Heliogravür', 'Autochrome', 'Dye transfer'], 'Fotokrom baskılar fotoğraf değil, fotoğraftan türetilen renkli litografilerdir; Avrupa ve Orta Doğu manzaralarını kartpostal ve albümlerle yaymışlardır.'),
  ('1892\'de Londra\'da Fotoğraf Derneği\'nden ayrılıp fotoğrafı bilimsel tekniğin değil sanatın konusu olarak gören fotoğrafçıların kurduğu topluluk hangisidir?', 'Kenetli Halka (The Linked Ring)', ['Kraliyet Fotoğraf Akademisi (resmî bir akademi)', 'Londra Kamera Kulübü', 'Gümüş Halka Kardeşliği'], 'The Linked Ring, piktoryalist fotoğrafçıların İngiltere\'deki öncü örgütüdür; yıllık sergileri "Photographic Salon" adıyla düzenlenmiştir.'),
  ('Stieglitz\'in 1920\'lerde çektiği bulut fotoğraflarına "Eşdeğerler" (Equivalents) adını vermesi ne anlama gelir?', 'Biçimlerin iç duyguların görsel karşılığı olarak görülmesi', ['Bulutların gerçek boyutlarında basılması ve fotoğrafçının gizli sanatı olarak', 'Her fotoğrafın aynı saatte çekilmesi', 'Fotoğrafların bir resmin kopyası olması'], 'Stieglitz bu soyut gökyüzü görüntülerini müziğe benzetmiş; konu değil, biçimlerin uyandırdığı duygu öne çıkmıştır.'),
  ('Alfred Stieglitz\'in 1917\'den başlayarak yaklaşık yirmi yıl süren, yüzlerce fotoğraftan oluşan kompozit portresi hangi sanatçıyı konu alır?', 'Georgia O\'Keeffe', ['Frida Kahlo', 'Mary Cassatt', 'Gertrude Stein'], 'Stieglitz eşi O\'Keeffe\'yi elleri, yüzü ve bedeninin ayrıntılarıyla yüzlerce kez fotoğraflayarak tek bir portrenin sınırlarını aşmak istemiştir.'),
  ('Edward Steichen 1947-1962 yılları arasında hangi görevi yürütmüştür?', 'New York Modern Sanat Müzesi\'nin fotoğraf bölümü direktörlüğü', ['LIFE dergisinin fotoğraf editörlüğü', 'Vogue dergisinin baş fotoğrafçılığı', 'ABD Kongre Kütüphanesi\'nin arşiv başkanlığı ve yalnızca fotoğraf arşivi yönetimi'], 'Steichen MoMA\'da fotoğraf bölümünü yöneterek büyük ölçekli sergiler düzenlemiş, yerine John Szarkowski geçmiştir.'),
  ('1917\'de üç aynalı bir düzenekle çektiği, ilk bilinçli soyut fotoğraflardan sayılan "Vortograf"larıyla tanınan fotoğrafçı kimdir?', 'Alvin Langdon Coburn', ['Man Ray', 'Christian Schad', 'Paul Strand'], 'Coburn, Vortisizm akımıyla ilişkili bu çalışmalarda aynaların çoğalttığı kırık biçimlerle konudan bağımsız görüntüler elde etmiştir.'),
  ('Paul Strand 1916\'da New York sokaklarında insanların doğal yüzlerini çekerken fark edilmemek için hangi hileye başvurmuştur?', 'Makinesine sahte bir objektif takıp yana doğru çekmek', ['Bir binanın çatısından teleobjektifle çekmek ve görünmez kalarak', 'Makineyi şapkasının içine gizlemek', 'Gece karanlığında güçlü flaş patlatmak'], 'Strand, önde sahte bir objektif bulunan, gerçek çekimi yandaki açıklıktan yapan bir makineyle konularına doğrudan bakmıyormuş gibi davranmıştır.'),
  ('Edward Weston\'ın 1930\'da bir teneke huninin önünde çektiği, sıradan bir sebzeyi heykelsi bir forma dönüştüren ünlü fotoğrafı hangisidir?', 'Biber No. 30', ['Lahana Yaprağı No. 1', 'Enginar No. 12', 'Patlıcan No. 7'], 'Weston, biberin kıvrımlarını uzun pozlama ve yumuşak ışıkla gövdeyi andıran bir forma dönüştürerek doğrudan fotoğrafın soyutlama gücünü göstermiştir.'),
  ('Edward Weston\'ın 8 × 10 inç büyük negatiflerinden büyütme yapmadan kontakt baskı almasının amacı nedir?', 'Negatifteki ayrıntının kayıpsız biçimde kâğıda geçmesi', ['Baskıların renkli görünmesini sağlamak', 'Görüntüye bilinçli bir bulanıklık katmak ve baskıda bilerek yumuşaklık yaratmak', 'Kâğıt ve banyo masrafını azaltmak'], 'Kontakt baskıda negatif kâğıda doğrudan değdirilir; araya objektif girmediğinden negatifin bütün keskinliği ve ton zenginliği korunur.'),
  ('Man Ray ve Lee Miller\'ın yaygınlaştırdığı solarizasyon (Sabattier etkisi) negatif ya da baskı üzerinde nasıl bir sonuç doğurur?', 'Tonlar kısmen ters döner, konturların çevresinde ince bir ışık halesi oluşur', ['Görüntü yalnızca mavi tonlara dönüşür', 'Bütün ayrıntılar eşit biçimde bulanıklaşır', 'Görüntü tamamen siyaha boyanır'], 'Banyo sırasında filme ya da kâğıda kısa süreli bir ikinci ışık verilince açık-koyu ilişkisi kısmen tersine çevrilir ve kenarlarda parlak bir çizgi belirir.'),
  ('Moholy-Nagy fotogramları neden "ışıkla resim" olarak tanımlamıştır?', 'Görüntü, boya yerine doğrudan ışığın duyarlı yüzeyde bıraktığı izlerle oluşur', ['Fotogramlar yalnızca gün ışığında çekilebilir', 'Fotogramda fosforlu boya kullanılır', 'Görüntü lamba ışığıyla kâğıda çizilir'], 'Fotogramda kamera ve lens bulunmaz; nesnelerin ışığı engellediği ve geçirdiği alanlar duyarlı kâğıtta ton oluşturur, bu yüzden ışık asıl "malzeme" olur.'),
  ('Moholy-Nagy\'nin 1937\'de ABD\'de, Chicago\'da kurduğu ve Bauhaus fikirlerini sürdüren okul hangisidir?', 'Yeni Bauhaus', ['Black Mountain Koleji ve Cranbrook Akademisi\'nin sanat dalı', 'Art Students League', 'Pratt Enstitüsü'], 'Moholy-Nagy Chicago\'da Yeni Bauhaus\'u açmış, okul sonradan Illinois Tasarım Enstitüsü adıyla sürmüştür.'),
  ('Sovyet eleştirmenlerinin 1928\'de Rodçenko\'nun fotoğraflarını "biçimci" diye eleştirmesinin temel nedeni nedir?', 'Alışılmadık açıların toplumsal içerikten çok biçime önem verdiği düşünülmüştü', ['Fotoğrafların renkli basılması', 'Çekimlerin yurt dışında yapılması', 'Yalnızca eski usul tekniklerin kullanılması'], 'Dik ve eğik açılar, yeni görüş biçimini ön plana çıkardığı için Sovyet ortamında toplumsal gerçekçilikten uzak bir "burjuva biçimciliği" olarak yorumlanmıştır.'),
  ('Berlin Dadacısı John Heartfield\'ın asıl soyadı Herzfeld iken adını İngilizceleştirmesinin gerekçesi nedir?', 'Birinci Dünya Savaşı sırasında Alman milliyetçiliğini protesto etmek', ['Amerika\'ya göç etmeyi planlaması', 'Kardeşinden ayrılmak istemesi', 'Bir dergide takma ad kullanma zorunluluğu'], 'Heartfield, savaş döneminin İngiliz düşmanlığı ortamında adını İngilizceleştirerek Alman milliyetçiliğine karşı kişisel bir başkaldırı göstermiştir.'),
  ('Hannah Höch\'ün Berlin Dada çevresindeki fotomontajlarında kadınların imgesinin sık işlenmesi hangi toplumsal olguyla ilişkilendirilir?', 'Weimar döneminde "yeni kadın" figürünün yükselişiyle', ['Kadınların seçme hakkının kaldırılmasıyla ve ordu sistemindeki değişikliklerle', 'Kırsal yaşama dönüş akımıyla', 'Hanedanlık rejiminin yeniden kurulmasıyla'], 'Höch, 1920\'lerin çalışan, bağımsız "yeni kadın" tipini ve değişen cinsiyet rollerini kolajlarında mizahla ele almıştır.'),
  ('Raoul Hausmann ve Hannah Höch gibi Berlinli sanatçıların "fotomontaj" terimini benimsemelerinde en çok hangi düşünce etkili olmuştur?', 'Kendilerini sanatçı değil, makine gibi birleştiren "monteur" saymak', ['Resmi yağlıboya geleneğinin devamı olarak görmek ve fotoğraf makinesi ile çalışmaya karşı çıkmak', 'Fotoğrafı tamamen reddetmek', 'Gerçekliği olduğu gibi kaydetmek'], 'Dadacılar kendilerini mühendis ya da montaj işçisi gibi gördükleri için "montaj" sözcüğünü seçmiş, sanatçı olma kibrini bilinçli olarak reddetmiştir.'),
  ('El Lissitzky\'nin 1924 tarihli "Yapıcı" adlı otoportresinde hangi iki imge üst üste getirilmiştir?', 'Yüzünü ve pergelle tutulan eli', ['Bir silah ve bir bayrak', 'Bir kitap ve bir kamera', 'İki ayrı yüz'], 'Fotogram etkisindeki otoportrede sanatçının başı ile çizim yapan el üst üste bindirilerek mühendis-sanatçı fikri anlatılır.'),
  ('Albert Renger-Patzsch\'in 1928\'de yayımlanan ve Yeni Nesnellik\'in bildirgesi sayılan kitabı hangisidir?', 'Dünya Güzeldir', ['Yirminci Yüzyılın İnsanları', 'Sanatta Biçimlerin Doğası', 'Zamanın Tanıkları'], 'Başlangıçta "Şeyler" adını taşıması düşünülen kitap, sıradan nesnelerin ve makinelerin keskin, doğrudan fotoğrafla güzelliğini öne çıkarır.'),
  ('Renger-Patzsch\'in fotoğrafçılık anlayışını Piktoryalizmden ayıran temel ilke hangisidir?', 'Fotoğrafın kendi tekniğiyle, resmi taklit etmeden net ve nesnel görüntü üretmesi', ['Baskıların yumuşak odakla elle işlenmesi', 'Fotoğrafın yalnızca stüdyoda üretilmesi', 'Gerçekliğin boyayla düzeltilmesi'], 'Renger-Patzsch resimsel taklidi reddetmiş, fotoğrafın kendine özgü gücünü keskinlik, ton değerleri ve nesnenin dokusunda görmüştür.'),
  ('Karl Blossfeldt\'in "Sanatın İlk Biçimleri" (Urformen der Kunst, 1928) kitabında yer alan fotoğrafların konusu nedir?', 'Büyütülmüş bitki sürgünleri, tomurcukları ve tohum başları', ['Endüstri tesisleri', 'Sokak portreleri', 'Gece kent manzaraları'], 'Blossfeldt, kendi yaptığı kameralarla bitkilerin ayrıntılarını büyüterek doğadaki mimari ve süsleme biçimlerinin kaynağını göstermeyi amaçlamıştır.'),
  ('Heykeltıraş ve öğretmen Karl Blossfeldt bitki fotoğraflarını başlangıçta neden çekmiştir?', 'Öğrencilerine doğadan tasarım örnekleri göstermek için', ['Bir botanik dergisine satmak için', 'Moda fotoğrafçılığına geçmek için', 'Savaş propagandası hazırlamak için ve savaş sonrası propaganda dergileri için'], 'Berlin\'de sanat okulunda öğretmenlik yapan Blossfeldt, bitkilerin form yapısını ders gereci olarak belgelemiş, bu çalışmalar sonradan sanat değeri kazanmıştır.'),
  ('Bir fotoğraf eleştirmeni, Blossfeldt\'in bir eğrelti otu ucunu büyüterek gotik kule gibi gösteren fotoğrafı için hangi yorumu yapabilir?', 'Doğa biçimlerinin mimari ve süsleme formlarıyla benzerliğini gösterdiği', ['Doğanın tahribini anlattığı', 'Soyut resmi doğrudan kopyaladığı', 'Bitkinin renk değiştirdiğini kanıtladığı'], 'Büyütme ve sade zemin, bitkinin kendi yapısal düzenini ortaya çıkarır; bu da form ile işlev arasındaki ilişkiyi mimari analojileriyle düşündürür.'),
  ('Dora Maar\'ın 1936 tarihli "Ubu Baba" fotoğrafı neden gerçeküstü fotoğrafın örneği sayılır?', 'Gerçek bir yaratığın yakın çekimi tanınmaz ve ürkütücü bir varlık gibi gösterilir', ['Bir portre kolajından oluşur', 'Boyalı bir tuvalin fotoğrafıdır', 'Bir ressamın atölyesini gösterir'], 'Fotoğraf, bir hayvan embriyosunu gizemli ve rahatsız edici bir yaratığa dönüştürerek bilinçdışı korkuları çağrıştırır.'),
  ('Hans Bellmer\'in 1930\'larda çektiği fotoğraflarda ana konu olan nesne hangisidir?', 'Eklemli, parçalanıp yeniden birleştirilen büyük bir kukla', ['Mimari maketler', 'Savaş uçakları', 'Kuru çiçekler'], 'Bellmer, kendi yaptığı kuklayı değişik biçimlerde diziliş ve yerleşimlerle fotoğraflayarak bedenin arzu ve şiddetle bağını sorgulamıştır.'),
  ('Macar doğumlu fotoğrafçı Gyula Halász "Brassaï" takma adını hangi kentten almıştır?', 'Doğduğu Brassó', ['Yaşadığı Paris\'ten', 'Eğitim gördüğü Budapeşte\'den', 'Çalıştığı Münih\'ten'], 'Halász, doğum yeri Brassó\'ya gönderme yapan "Brassaï" (Brassólu) adını kullanmıştır.'),
  ('André Kertész\'in 1933\'te aynalarla bozulmuş çıplak figürlerden oluşturduğu dizi hangisidir?', 'Çarpıtmalar (Distortions)', ['Hareket Çalışmaları (hareket analizi dizisi)', 'Yeni Görüş', 'Aynadaki Beden'], 'Kertész, eğri ve dışbükey aynalarda çıplak modelleri fotoğraflayarak gerçeküstü etkili, bedeni uzatan ve kıvıran görüntüler elde etmiştir.'),
  ('Küçük Leica\'sıyla Paris\'te şiirsel gündelik anları ve alışılmadık açıları yakalayan André Kertész, hangi anlayışın öncüleri arasında anılır?', 'Küçük makineyle yaşamı doğal akışında yakalayan muhabir fotoğrafçılığının', ['Büyük format makineyle çalışan manzara fotoğrafçılığının ve bir portre stüdyosunda çalışan ressamlığın', 'Stüdyo reklam fotoğrafçılığının', 'Mikrofotoğrafçılığın'], 'Kertész, Leica ile alışılmadık açıları ve yaşamın küçük anlarını yakalayarak Cartier-Bresson gibi sonraki kuşakları etkilemiştir.'),
  ('Henri Cartier-Bresson\'un 1932 tarihli "Saint-Lazare İstasyonu Arkası" fotoğrafında göze çarpan ana görüntü nedir?', 'Su birikintisinin üzerinden atlayan adam', ['Trene binen bir kadın', 'Meydanda koşan bir köpek ve çevrede kimse bulunmaması', 'Bir tren makinisti'], 'Sıçrayan adamın yansıması suyun yüzeyinde yakalanmış, fotoğraf Cartier-Bresson\'un "belirleyici an" anlayışının tipik bir örneği sayılmıştır.'),
  ('Çocuk yaşta fotoğraf çekmeye başlayan ve ailesinin eğlencelerini, uçuş denemelerini ve yarışları kaydeden Fransız kimdir?', 'Jacques Henri Lartigue', ['Eugène Atget', 'Robert Doisneau', 'Brassaï'], 'Lartigue yedi yaşında makinesini alarak aile yaşamını canlı kareler halinde belgelemiş, ancak yaşlılığında ün kazanmıştır.'),
  ('Julia Margaret Cameron\'a fotoğraf makinesi nasıl geçmiştir?', 'Kızı ve damadı ona 1863\'te doğum günü hediyesi olarak vermiştir', ['Kocası Londra\'dan getirmiştir', 'Darwin ondan satın almıştır', 'Bir fotoğraf stüdyosundan miras kalmıştır ve yakın arkadaşı Tennyson\'dan armağanla'], 'Cameron kırk sekiz yaşında kendisine armağan edilen makineyle Wight Adası\'nda çalışmaya başlamıştır.'),
  ('Julia Margaret Cameron, Tennyson\'ın hangi eserini kendi fotoğraflarıyla resimlemiştir?', 'Kral Arthur Öyküleri', ['Hamlet', 'Sonnetler', 'Paradise Lost'], 'Alfred Tennyson\'ın dostu olan Cameron, 1874-75\'te şairin Arthur Efsaneleri üzerine eserini resimleyen fotoğraflar hazırlamıştır.'),
  ('Weegee\'nin 1945\'te yayımlanan fotoğraf kitabının adı nedir?', 'Çıplak Şehir (Naked City)', ['Kent Gecesi', 'Karanlık Sokaklar', 'Kaybolmuş New York (hayalî bir kent anlatısı)'], '"Naked City" kitabı New York\'un suç, kaza ve gece hayatı görüntülerini topladı; sonradan aynı adlı filme esin verdi.'),
  ('Henry Luce\'un 1936\'da kurduğu LIFE dergisinin fotoğraf haberciliğine temel katkısı nedir?', 'Fotoğraf dizilerinin metinden çok anlatımı üstlenen "foto-öykü" biçiminin yaygınlaşması', ['Yalnızca renkli fotoğraf basması', 'Fotoğrafların ödüllendirilmesi', 'Yalnızca portre yayımlaması'], 'LIFE fotoğraf dizilerini görsel anlatının merkezine koyarak haberi ve öyküyü fotoğraflarla anlatan bir biçim geliştirmiştir.'),
  ('W. Eugene Smith\'in 1948\'de LIFE\'ta yayımlanan "Taşra Doktoru" dizisi neyi konu almıştır?', 'Colorado\'da küçük bir kasabada çalışan doktorun gündelik yaşamını', ['İkinci Dünya Savaşı cephesini', 'Japonya\'daki sanayi kazasını', 'Bir tıp okulunu'], 'Smith, kasabadaki Dr. Ceriani\'yi haftalarca izleyerek bir foto-öykü hazırlamış, bu dizi foto-deneme türünün başyapıtı sayılmıştır.'),
  ('Almanya\'da 1890\'larda kurulan "Berliner Illustrirte Zeitung" fotoğraf tarihinde neden önemlidir?', 'Foto muhabirliğinin ilk büyük ticari örneklerinden olup Salomon gibi isimlere sayfalarını açmıştır', ['Yalnızca gravür resimlere yer vermiştir', 'Renkli fotoğrafı ilk kez basmıştır', 'Hükümetin resmi yayını olarak çıkmıştır'], 'Dergi, 1920-30\'larda fotoğrafın haberdeki rolünü artıran ve milyonluk tirajlara ulaşan örneklerdendir.'),
  ('Gordon Parks\'ın 1942\'de FSA için çektiği "Amerikan Gotiği" fotoğrafında kim gösterilir?', 'Temizlikçi kadın Ella Watson\'ı Amerikan bayrağı önünde süpürgeyle', ['Bir çiftçi çifti', 'Bir okul öğretmeni', 'Bir çocuk işçi'], 'Parks, Grant Wood\'un ünlü tablosuna gönderme yaparak ırk ayrımcılığını eleştirmiş ve fotoğrafıyla Amerikan rüyasının çelişkilerine dikkat çekmiştir.'),
  ('Walker Evans\'ın 1938\'de MoMA\'da gerçekleşen ilk fotoğraf kitabı ve sergisi hangisidir?', 'Amerikan Fotoğrafları', ['Aziz Gelin', 'Bir Ülke', 'Tuzlu Toprak'], '"American Photographs", Evans\'ın düz, belgesel yaklaşımını gösterdi ve modern fotoğraf sergilerinde dönüm noktası sayıldı.'),
  ('George Rodger\'ın 1945\'te Bergen-Belsen toplama kampında çektiği fotoğraflar onu hangi karara götürmüştür?', 'Savaş fotoğrafçılığını bırakıp Afrika\'nın halklarını belgelemeye yönelmek', ['Savaşa bir daha fotoğraf makinesiyle gitmemek', 'Cephe muhabirliğine daha çok girmek', 'Magnum\'dan ayrılmak'], 'Rodger, ölü yığınlarının arasında bile kompozisyon kaygısı duyduğunu fark edip dehşete düşmüş, sonra Afrika\'da Nuba halkını fotoğraflamaya yönelmiştir.'),
  ('Larry Burrows\'un 1966\'da LIFE\'ta yayımlanan "Uzanan El" fotoğrafı nerede çekilmiştir?', 'Vietnam\'da, yaralı bir deniz piyadesinin arkadaşına uzandığı sahnede', ['Kore\'de bir cephe hastanesinde', 'Normandiya\'da bir sığınakta', 'Afganistan\'da bir köyde'], 'Burrows, Vietnam Savaşı\'nı LIFE için renkli film üzerine fotoğraflayan öncülerdendir; "Reaching Out" yaralı bir askerin arkadaşına uzanışını gösterir.'),
  ('Malcolm Browne\'ın 1963\'te Saygon\'da çektiği fotoğraf neyi gösterir?', 'Budist rahip Thích Quảng Đức\'in protesto amacıyla kendini yakmasını', ['Bir sokaktaki infazı', 'Bir çocuğun napalmdan kaçışını', 'Bir tankın karşısındaki adamı'], 'Browne\'ın bu fotoğrafı yönetime karşı protesto eylemini dünya kamuoyuna taşımış, 1964\'te Pulitzer ödülü almıştır.'),
  ('1989\'da Pekin\'deki Tiananmen olaylarının ardından çekilen "Tank Adam" fotoğrafında ne görülür?', 'Bir adamın tank konvoyunun yolunu tek başına kesmesi', ['Tankların meydana girmesi', 'Bir askerin tanka çıkması', 'Bir çocuğun tank üzerinde oturması ve tank üstünde gösteri yapması'], 'Alışveriş torbalarıyla yolun ortasında duran adam, bir tank kolunun önünü kesmiş; Beijing Hotel\'in balkonundan çeken birkaç fotoğrafçı bu görüntüyü yakalamıştır.'),
  ('Richard Drew\'un 11 Eylül 2001\'de çektiği ve yayımlandığında büyük tartışma yaratan fotoğrafı neyi gösterir?', 'Kuzey Kulesi\'nden düşen bir kişiyi', ['İtfaiyecilerin enkazdan çıkışını', 'Ground Zero\'daki gökyüzünü', 'İkiz kulelerin çökmesini'], '"Düşen Adam" fotoğrafı, ölüm anının sunulması konusundaki etik tartışmayı ve basının sorumluluğunu gündeme getirmiştir.'),
  ('Sam Shere\'in 1937\'de New Jersey\'de çektiği ve alevler içindeki dev bir araç görüntüsünü yakalayan fotoğraf hangi olayla ilgilidir?', 'Hindenburg zeplininin yanması', ['Titanik\'in batışı ve ardından gelen kurtarma çalışması', 'Hava saldırısı', 'Bir tren kazası'], 'Hindenburg felaketi, zeplin yolculuğunun sonunu getirmiş; radyo muhabirinin haykırışı ve fotoğraflar olayı ölümsüzleştirmiştir.'),
  ('Dallas\'ta 1963\'te Robert Jackson\'ın çektiği ve Pulitzer ödülü alan fotoğraf hangi olayı belgeler?', 'Jack Ruby\'nin Lee Harvey Oswald\'ı vurma anını', ['Başkan Kennedy\'nin arabadan inişini ve ardından basına konuşması', 'Kennedy\'nin vurulduğu anı', 'Johnson\'ın yemin törenini'], 'Jackson, Oswald\'ın polis karakolundan çıkarıldığı sırada Ruby\'nin ateş ettiği anı, deklanşöre tam zamanında basarak yakalamıştır.'),
  ('Margaret Bourke-White\'ın 1946\'da Hindistan\'da çektiği ve bir iğ başında oturan liderin portresi hangi ismi gösterir?', 'Mahatma Gandhi', ['Jawaharlal Nehru', 'Muhammed Ali Cinnah', 'Rabindranath Tagore'], 'Bourke-White, Gandhi\'nin çıkrık başındaki sade yaşamını LIFE için fotoğraflayarak bağımsızlık hareketinin simge görüntülerinden birini yaratmıştır.'),
  ('Fotoğrafların telgraf kablosuyla gönderilmesini sağlayan Bartlane sistemi 1920\'lerin başında hangi iki şehir arasında kullanılmıştır?', 'Londra ile New York', ['Paris ile Berlin', 'Roma ile Viyana', 'Moskova ile Pekin'], 'Bartlane kablolu resim iletimi, görüntüyü kodlanmış noktalarla Atlantik\'in ötesine saatler içinde yollayarak haber fotoğrafçılığını hızlandırmıştır.'),
  ('1935\'te Associated Press\'in kurduğu Wirephoto ağı foto muhabirliğine hangi değişikliği getirmiştir?', 'Haber fotoğraflarının telefon hatlarıyla gazetelere birkaç dakikada ulaşması', ['Renkli haber fotoğrafının başlaması', 'Fotoğrafların yalnızca posta ile gönderilmesi', 'Fotoğrafçıların ajans binasında çalışmaya zorlanması'], 'Wirephoto, uzak olaylardan fotoğrafların aynı gün gazetelere ulaşmasını sağlayarak haberin hızını artırmıştır.'),
  ('ABD\'de Pulitzer ödüllerinde fotoğraf dalı 1968\'den itibaren hangi iki kola ayrılmıştır?', 'Özel fotoğraf (feature) ve son dakika haber fotoğrafı', ['Siyah-beyaz ve renkli', 'Savaş ve barış', 'Portre ve manzara'], 'Haber fotoğrafı, ani gelişen olayların fotoğrafı (spot/breaking news) ile gündelik yaşamı anlatan öykülü fotoğraf (feature) olarak iki ayrı ödüle bölünmüştür.'),
  ('Hasselblad Vakfı\'nın 1980\'de başlattığı ve fotoğraf dünyasının en prestijli ödüllerinden biri sayılan ödülün ilk sahibi kimdir?', 'Lennart Nilsson', ['Henri Cartier-Bresson', 'Ansel Adams', 'Richard Avedon'], 'Gothenburg\'daki vakıf ödülünü ilk kez, insan embriyosunun gelişimini fotoğrafladığı çalışmalarıyla tanınan İsveçli fotoğrafçıya vermiştir.'),
  ('Garry Winogrand\'ın sokak fotoğraflarında sıkça kullandığı belirgin kompozisyon özelliği nedir?', 'Makineyi eğik tutarak ufku yatıktan çıkarması', ['Hep kuş bakışı bir açıdan çekmesi', 'Tüm kareleri tam simetrik düzenlemesi', 'Yalnızca tek bir nesneyi merkeze koyması ve kareyi simetrik düzenlemesi'], 'Geniş açılı objektifle yaklaşıp makineyi eğen Winogrand, hareketli kentte dinamik ve gergin kareler elde etmiştir.'),
  ('Winogrand\'ın 1975 tarihli kitabı "Kadınlar Güzeldir" hangi eleştiriyle karşılanmıştır?', 'Kadınları nesneleştirip gözetlemek biçiminde olduğu eleştirisiyle', ['Yalnızca renkli basıldığı için', 'Çok az fotoğraf içerdiği için', 'Fotoğrafların gerçek olmadığı iddiasıyla'], 'Kitap, caddelerde yürüyen kadınların izinsiz çekilmiş görüntülerinden oluşmuş; kimi eleştirmenler bakış biçimini sorunlu bulmuştur.'),
  ('Lee Friedlander\'ın sokakta fotoğraf çekerken kendi gölgesini ya da yansımasını kadraja sokması neyi gösterir?', 'Fotoğrafçının sahneye kendini bilinçli olarak yerleştirmesini', ['Makinenin kusuru', 'Fotoğrafın sahneleme olduğunu', 'Işığı ölçme zorunluluğunu'], 'Friedlander, gölge ve yansımaları kullanarak fotoğrafçıyı izleyiciden gizlenen bir tanık olmaktan çıkarıp görüntünün parçası yapmıştır.'),
  ('Diane Arbus\'un 1967 tarihli "Roselle\'de İkizler" fotoğrafı neden bu denli yorumlanmıştır?', 'Benzer iki kızın hem özdeşliği hem de aralarındaki ince farkı sergilemesi', ['İkizlerin ünlü olması', 'Fotoğrafın renkli olması', 'İkizlerin farklı mekânlarda çekilmesi'], 'Aynı giyimli iki kız, kimliğin bütünlüğü ve ikilik üzerine rahatsız edici bir gerilim yaratır.'),
  ('Diane Arbus\'un fotoğraflarında hangi biçimsel seçim belirleyicidir?', 'Kareye yakın, çoğunlukla flaşlı ve doğrudan bakışlı portreler', ['Panoramik manzaralar', 'Soyut ışık oyunları', 'Uzaktan teleskopik çekimler'], 'Arbus, kenar kişilerle açık, doğrudan göz teması kuran kareler çekmiş; flaş kullanımı yüzlerdeki ayrıntıyı vurgulamıştır.'),
  ('Helen Levitt\'in 1940\'larda New York sokaklarında en çok fotoğrafladığı konu hangisidir?', 'Tebeşirle çizim yapan ve oynayan çocuklar', ['Gece kulüpleri', 'Fabrika işçileri', 'Moda mankenleri'], 'Levitt, yoksul mahallelerde çocukların oyun ve çizimlerini, kendiliğinden ve şiirsel bir yaklaşımla belgelemiştir.'),
  ('Saul Leiter\'in 1940-50\'lerde New York\'ta çektiği renkli sokak fotoğraflarının ayırt edici özelliği nedir?', 'Buğulu cam, yağmur ve yansımalar arkasından resimsel bir kompozisyon', ['Keskin siyah-beyaz kontrast', 'Geniş açıyla portre', 'Çıplak flaş aydınlatması'], 'Leiter, pencere, şemsiye ve buğu gibi engellerle kadrajı kısmen kapatarak soyut ve resimsel sahneler yaratmıştır.'),
  ('1976\'da MoMA\'da William Eggleston\'a verilen ilk büyük renkli fotoğraf sergisi neden bir dönüm noktası sayılır?', 'Renkli fotoğrafın ciddi sanat olarak kabul edilmesini sağlaması', ['İlk dijital fotoğraf sergisi olması', 'Yalnızca siyah-beyaz yapıtlara yer vermesi ve siyah-beyazın tamamen reddedilmesi', 'Fotoğrafın ilk kez müzede sergilenmesi'], 'Sergi, o zamana dek reklam ve amatör işi sayılan rengi sanatın aracı olarak onurlandırmış, eleştirmenler sert tepki göstermiştir.'),
  ('Stephen Shore\'un 1972-73 yıllarında ABD\'de araba yolculuğunda çektiği ve çoğu kez yemek tabağı, otel odası gibi sıradan konuları içeren dizisinin adı nedir?', 'Amerikan Yüzeyleri', ['Alışılmadık Yerler', 'Kaybolmuş Amerika', 'Yol Notları'], 'Shore\'un renkli, amatör anlık fotoğraf estetiğini bilinçli kullandığı bu dizi "American Surfaces" adıyla yayımlanmıştır.'),
  ('Joel Meyerowitz\'in 1978 tarihli "Cape Light" kitabı hangi alanla ilişkilidir?', 'Cape Cod\'da gün ışığının renkli manzara ve ev çevrelerine etkisi', ['Karanlık oda teknikleri', 'Savaş muhabirliği', 'Mikroskopik fotoğrafçılık'], 'Meyerowitz, büyük formatta Cape Cod kıyılarındaki ışık ve renk değişimlerini görsel anlatının ana konusu yapmıştır.'),
  ('Japonya\'da 1968\'de çıkan "Provoke" dergisinin fotoğraf için önerdiği üç özellik hangisidir?', 'Grenli, bulanık, odak dışı', ['Keskin, parlak, renkli', 'Simetrik, düzenli, durağan', 'Soluk, sade, minimal'], '"Are, bure, boke" olarak bilinen bu estetik, görsel gerçekliğin kesin ve nesnel aktarımına karşı kişisel algıyı vurgular.'),
  ('Shomei Tomatsu\'nun "Nagasaki 11:02" serisinde en çok bilinen görüntü hangisidir?', 'Bomba anında durmuş kol saati', ['Yıkık bir tapınak', 'Kâğıttan turna', 'Güneşe bakan bir çocuk ve bir kız çocuğu'], 'Tomatsu, atom bombası sonrasında eriyen eşyaları ve sakat kalan insanları fotoğraflamış; 11.02\'de durmuş saat bu serinin simgesidir.'),
  ('Nobuyoshi Araki\'nin 1971 tarihli "Duygusal Yolculuk" çalışması hangi temayı işler?', 'Evlilik balayını ve eşiyle ilişkisini', ['Kent mimarisini', 'Savaş sonrası yıkımı ve eşinden ayrılığı', 'Doğa manzaralarını'], 'Araki, kendi balayını bir fotoğraf günlüğü haline getirerek özel yaşamı sanatın konusu yapmıştır.'),
  ('Hiroshi Sugimoto\'nun "Sinemalar" serisinde tüm bir filmin süresi boyunca pozlanmış bir sinema perdesi nasıl görünür?', 'Boş, parlak beyaz bir dikdörtgen olarak', ['Karanlık bir kare olarak', 'Çok renkli bir kaos olarak ve filmden alınmış tek bir kare olarak', 'Filmdeki ilk kare olarak'], 'Perdedeki bütün ışık birikip beyaz bir alan oluşturur; böylece zamanın görüntüde biriktiği gösterilir.'),
  ('Hiroshi Sugimoto\'nun "Deniz Manzaraları" dizisindeki ortak özellik nedir?', 'Aynı kompozisyonda ufku ortadan bölen, yalnız gökyüzü ve deniz içeren görüntüler', ['Fırtınalı dalgaların hareketli kareleri', 'Plajlardaki insanlar', 'Gün batımındaki renkli gökyüzü'], 'Sugimoto, dünyanın farklı denizlerini aynı yerleşimle çekerek zamansızlık ve sadelik duygusu yaratmıştır.'),
  ('Gordon Parks\'ın FSA sonrasında fotoğraf muhabirliğine geçtiği ve ırkçılıkla ilgili dizileri yayımladığı dergi hangisidir?', 'LIFE', ['Vogue', 'Harper\'s Bazaar', 'Look'], 'Parks, LIFE için moda ve toplumsal konulu çalışmalar yapan ilk siyah fotoğrafçılardan biri olmuştur.'),
  ('Ernst Haas\'ın 1953\'te LIFE\'ta yayımlanan renkli foto-denemesi hangi şehri anlatır?', 'New York', ['Paris', 'Tokyo', 'Roma'], 'Haas, kent yaşamını renk ve hareketle şiirsel biçimde anlatan bu öykü ile renkli fotoğraf muhabirliğini yaygınlaştıran isimlerden biri olmuştur.'),
  ('Richard Avedon\'ın portrelerinde sık görülen düz beyaz fon neyi sağlar?', 'Modeli bağlamından koparıp yüzüne ve duruşuna odaklanılmasını', ['Modelin evi ve mesleğiyle ilgili ipuçlarının zengin biçimde okunmasını', 'Karanlık ve dramatik bir gölge oyununun oluşmasını', 'Fotoğrafın renkli basıma daha elverişli hale gelmesini'], 'Avedon, süssüz beyaz zeminde ünlüleri ve sıradan insanları eşit biçimde, olanca kusurlarıyla göstermiştir.'),
  ('Richard Avedon\'ın 1979-84 arasında ABD\'nin batısındaki işçileri, çiftçileri ve çobanları beyaz fonda çektiği dizinin adı nedir?', 'Amerikan Batısı\'nda', ['Kovboy Ülkesi', 'Yeni Sınır', 'Taşra Portreleri'], 'Dizi, 1985\'te Amon Carter Müzesi\'nde sergilenmiş ve sıradan insanların dramatik portrelerini sergilemiştir.'),
  ('Irving Penn\'in 1948\'de stüdyosunda iki duvarı birleştirerek oluşturduğu ve modelleri sıkışık bir köşede çektiği portre serisi hangisidir?', 'Köşe portreleri', ['Küçük meslekler', 'Sigaralar', 'Çiçekler'], 'Penn, ünlüleri iki ahşap panelin oluşturduğu dar alanda çekerek rahatsızlık ve yakınlık hissi yaratmıştır.'),
  ('Irving Penn Vogue için çalıştığı sırada hangi sanat yönetmeniyle yakın iş birliği yapmıştır?', 'Alexander Liberman', ['Alexey Brodovitch', 'Carmel Snow', 'Erwin Blumenfeld'], 'Vogue\'un sanat yönetmeni Liberman, Penn\'i ilk kapakla başlayıp onlarca yıl sürecek iş ilişkisine yönlendirmiştir.'),
  ('Edward Steichen\'in 1923\'ten itibaren Condé Nast için çalışması moda fotoğrafında neyi değiştirmiştir?', 'Daha keskin, modernist ve stüdyoya dayalı bir yaklaşımı yerleştirmiştir', ['Yalnızca renkli basımı getirmiştir', 'Dergileri fotoğraftan arındırmıştır', 'Modellerin sokağa çıkarılmasını getirmiştir'], 'Steichen, Vogue ve Vanity Fair için keskin odaklı modernist moda fotoğrafını başlatan isimlerden biri olmuştur.'),
  ('Horst P. Horst\'un 1939\'da çektiği "Mainbocher Korse" fotoğrafında modelin arkadan çekilmesi neyi gösterir?', 'Korsenin bağcıklarını ve ince bir kompozisyonu bir heykel gibi', ['Modelin yüzünü', 'Bir podyum şovunu', 'Bir sokak gösterisini'], 'Horst, sırttaki bağcıklara odaklanıp sahneyi ışıkla kabartmış; fotoğraf stüdyo moda çekiminin başyapıtı sayılır.'),
  ('Guy Bourdin\'in 1970\'lerdeki Charles Jourdan reklamları moda fotoğrafında hangi yenilikle bilinir?', 'Ürünü ikinci plana atıp gizemli ve rahatsız edici anlatılar kurması', ['Ürünü büyük çekimle öne çıkarması', 'Siyah-beyaz çekmesi', 'Gerçek mağazalarda çalışması'], 'Bourdin, ayakkabıyı gösterirken bile gerilimli, sinematik ve gerçeküstü sahneler hazırlamıştır.'),
  ('Carleton Watkins\'in 1861\'de çektiği Yosemite fotoğraflarının ABD\'de nasıl bir sonucu olmuştur?', 'Kongre\'nin 1864\'te Yosemite\'yi koruma altına alma kararına katkı vermesi', ['Vadinin turizm için satılması', 'Çevrenin kirlenmesi', 'Bölgenin işgal edilmesi'], 'Watkins\'in kocaman cam negatifleri Washington\'da gösterilerek vadinin korunması gerektiği fikri güçlenmiştir.'),
  ('William Henry Jackson\'ın 1871\'de Yellowstone\'u fotoğraflaması ABD\'de hangi gelişmeye zemin hazırlamıştır?', '1872\'de Yellowstone\'un ilk milli park ilan edilmesine', ['Bölgede madenlerin açılmasına', 'Savaşa', 'Eyaletin kurulmasına'], 'Hayden seferiyle giden Jackson\'ın görüntüleri Kongre üyelerini ikna etmiş, alan milli park yapılmıştır.'),
  ('Timothy O\'Sullivan\'ın 1870\'lerde Batı ABD\'yi keşif seferlerinde fotoğraflaması hangi tür görüntülerle bilinir?', 'Çorak, ıssız çöl ve kanyon manzaralarını yalın bir kompozisyonla', ['Şehir portrelerini', 'Savaş sahnelerini', 'Hayvan portrelerini'], 'O\'Sullivan, jeolojik seferlerde kıtanın ıssız manzaralarını boşluk duygusu veren bir keskinlikle görüntülemiştir.'),
  ('Edward Curtis\'in çalışmalarına yönelik başlıca eleştiri nedir?', 'Kimi sahnelerin ve giysilerin sahnelenip yerlilere "yok olan ırk" imajı verilmesi', ['Teknik açıdan kötü olması', 'Çok fazla renk kullanması', 'Kimsenin ilgisini çekmemesi'], 'Curtis, bazı fotoğraflarda modern öğeleri silip kostümler giydirerek romantik bir geçmiş yaratmıştır.'),
  ('Eliot Porter\'ın renkli doğa fotoğraflarından oluşan 1962 tarihli Sierra Club kitabı hangi sözden adını alır?', 'Doğada Yaşamın Korunması', ['Doğanın Uyumu', 'Büyük Batı', 'Vahşi Sessizlik'], 'Henry David Thoreau\'dan alınan başlığı taşıyan kitap, renkli film ile doğayı sanat düzeyinde gösteren ilk büyük basımlardandır.'),
  ('Étienne-Jules Marey\'in 1882\'de geliştirdiği "fotoğraf tüfeği" ne işe yarıyordu?', 'Bir kuşun kanat çırpışını saniyede on iki kare olarak kaydetmeye', ['Uzaktaki yıldızların fotoğraflarını çekilen en büyük teleskop merceğiyle birleştirmeye', 'Karanlık odada insan gözünün göremediği kızılötesi ışığı kâğıda aktarmaya', 'Fotoğrafı doğrudan duvara yansıtarak büyük boyutlu baskı elde etmeye'], 'Tüfek biçimli cihaz, hareketin evrelerini tek bir plaka üzerinde ardışık karelerle kaydeden bir kronofotoğraf makinesiydi.'),
  ('Marey\'in kronofotoğrafı ile Muybridge\'in ardışık makine sistemi arasındaki başlıca fark nedir?', 'Marey tek makinede, çoğu kez tek plakada toplardı; Muybridge her kare için ayrı makine kullandı', ['Marey yalnızca renkli plakalarla çalışarak hareketi sentetik biçimde yeniden üretmeye çalıştı', 'Marey her kare için ayrı makine kurdu; Muybridge bütün evreleri tek plakada topladı', 'Marey yalnızca makine hareketini inceledi, Muybridge ise yalnızca hayvanların hareketini kaydetti'], 'Muybridge her kare için ayrı makine kullanırken Marey, hareketli evreleri tek makinede ve çoğu kez tek plaka üzerinde birleştirmiştir.'),
  ('Harold Edgerton\'ın MIT\'de geliştirdiği stroboskopik flaş fotoğrafa neyi mümkün kılmıştır?', 'Saniyenin milyonda biri kadar kısa sürelerle hızlı olayları dondurmayı', ['Çok uzun pozlarda yıldız izlerini çıkarmayı', 'Renkli filmi doğrudan negatife çevirmeyi', 'Görüntüyü kablosuz iletmeyi'], 'Edgerton, çok kısa flaş süreleriyle kurşunun elmayı delişi ve süt damlası taçlanması gibi hızlı olayları görünür kılmıştır.'),
  ('Edgerton\'ın 1957 tarihli "Süt Damlası Tacı" fotoğrafında görülen olay nedir?', 'Süt damlasının yüzeye çarpınca çevresinde taç biçimi oluşturması', ['Bir camın kırılışı', 'Bir kuşun kanat vuruşu', 'Bir balonun patlaması'], 'Elektronik flaş saniyenin çok küçük bir kesrinde yanarak damlanın çarpma anında oluşan taç şeklini dondurmuştur.'),
  ('Wilson Bentley\'in 1885\'ten başlayarak yaptığı çalışmanın konusu nedir?', 'Kar tanelerinin mikroskoba bağlı makineyle fotoğraflanması', ['Kuşların göç yollarının hava fotoğrafıyla belgelenmesi ve gözlem istasyonlarında', 'Ay yüzeyinin teleskopla yakın çekimi', 'Yıldırım çakmalarının gece pozlamasıyla izlenmesi'], 'Vermont\'lu çiftçi Bentley, mikrofotoğraf düzeneğiyle binlerce kar tanesini kaydederek bunların büyük çeşitliliğini göstermiştir.'),
  ('Voyager 1\'in 1990\'da yaklaşık altı milyar kilometre uzaklıktan çektiği ve Dünya\'yı küçücük bir nokta olarak gösteren fotoğraf ne diye anılır?', 'Soluk Mavi Nokta', ['Mavi Mermer', 'Dünya Doğuşu', 'Büyük Mavi'], 'Carl Sagan\'ın önerisiyle çekilen fotoğraf, evrende Dünya\'nın küçüklüğüne ve insanlığın kırılganlığına dikkat çekmiştir.'),
  ('Apollo 17 mürettebatının 1972\'de yolda çektiği, Dünya\'nın tam aydınlık yüzünü gösteren fotoğraf hangi adla bilinir?', 'Mavi Mermer', ['Dünya Doğuşu', 'Soluk Mavi Nokta', 'Yaratılışın Sütunları'], '"Blue Marble", Güney Kutbu\'nun altta göründüğü, Dünya\'nın bütünüyle aydınlık göründüğü en çok çoğaltılan görüntülerden biridir.'),
  ('Hubble Uzay Teleskobu\'nun 1990\'daki fırlatılışından sonra ilk görüntülerinin bulanık çıkmasının nedeni nedir?', 'Ana aynadaki küresel sapma kusuru', ['Güneş panellerinin gölgelemesi ve aşırı soğuk yörünge', 'Kameranın yanlış odaklanması', 'Yörüngenin çok alçak olması'], 'Ayna hatalı biçimde taşlanmış olduğundan 1993\'teki servis görevinde düzeltici optik takılmıştır.'),
  ('Apollo 11\'de Ay yüzeyinde çekilen fotoğrafların çoğunda Neil Armstrong\'un görünmemesinin nedeni nedir?', 'Çoğu kareyi Armstrong\'un kendisinin çekmiş olması', ['Armstrong\'un fotoğraf çektirmeyi reddetmesi çünkü makine yalnızca Aldrin\'de olmuştur', 'Filmin yalnızca Aldrin\'e ait olması', 'Armstrong\'un makinesinin bozulması'], 'Hasselblad makinesi ağırlıklı olarak Armstrong\'da olduğundan çoğu kare Aldrin\'i gösterir; Armstrong yalnız birkaç karede, çoğunlukla yansıma olarak görünür.'),
  ('24 Ekim 1946\'da White Sands\'ta bir V-2 roketiyle yaklaşık 105 km yüksekliğe çıkarılan kamera ne yapmıştır?', 'Dünya\'nın uzaydan ilk yüksek irtifa fotoğraflarını çekmiştir', ['Ay\'ı fotoğraflamıştır', 'Atmosferde kamera denemesi yapmıştır', 'Güneş\'in tutulmasını belgelemiştir'], 'Roketteki 35 mm film kamerası, Dünya\'nın uzaydan görünüşünü kaydeden ilk fotoğrafları üretmiştir.'),
  ('Sovyet yönetiminde Nikolay Yejov\'un, Stalin\'le birlikte yürüdüğü fotoğraftan silinmesi hangi uygulamanın örneğidir?', 'Siyasi nedenlerle kişilerin fotoğraflardan silinmesi', ['Sansürsüz yayıncılığın', 'Fotoğraf yarışmalarının', 'Sovyet fotoğraf sanatının'], 'Rejim, gözden düşenleri tarihten silmek için fotoğraflarda rötuş yapmış, Yejov\'un silinmesi bunun en ünlü örneğidir.'),
  ('David King\'in 1997 tarihli kitabı "Komiser Kayboluyor" neyi belgeler?', 'Stalin döneminde sahte ve rötuşlu fotoğrafların karşılaştırmalı örneklerini', ['Rusya\'daki sanatçıların yaşamını', 'Fotoğraf makinelerinin tarihini', 'Moskova\'nın mimarisini'], 'King, Stalin dönemi resmi fotoğraflarının orijinal ve düzeltilmiş hâllerini yan yana koyarak tarihin nasıl yeniden yazıldığını göstermiştir.'),
  ('1982\'de National Geographic kapağında iki Giza piramidinin birbirine yaklaştırılmasının nedeni nedir?', 'Yatay fotoğrafın dikey kapağa sığması için bilgisayarla kaydırılması', ['Fotoğrafçının iki piramidi çok yakından görmesi ve yanlış koordinat vermesi', 'Güneş ışığının piramitleri çarpıtması', 'Dergi editörünün yanlış koordinat vermesi'], 'Dergi, görüntüyü dikey formata uydurmak için dijital olarak sıkıştırmış ve bu, fotoğraf etiğini yeniden gündeme getirmiştir.'),
  ('"Cerrahın Fotoğrafı" olarak bilinen 1934 tarihli fotoğraf neden ünlüdür?', 'Loch Ness canavarını gösterdiği sanılan ve sonradan sahte olduğu anlaşılan görüntü olması', ['İlk röntgen fotoğrafı olması', 'Bir ameliyatı belgelemesi', 'Savaşta yaralıları göstermesi'], 'Oyuncak denizaltıya takılan sahte başla çekilen görüntü, onlarca yıl sonra 1994\'te itirafla gerçek dışı olduğu doğrulanmıştır.'),
  ('1917\'de Cottingley\'de iki kuzenin "peri" fotoğrafları kimin dikkatini çekip destek almıştır?', 'Arthur Conan Doyle', ['H. G. Wells', 'Charles Darwin', 'Oscar Wilde'], 'Sherlock Holmes\'un yazarı fotoğrafları gerçek sanıp savunmuş; kızlar ise onlarca yıl sonra kâğıt kesmelerle yaptıklarını itiraf etmiştir.'),
  ('William Mumler\'in 1860\'larda ünlenmesine yol açan fotoğraflar nasıl elde edilmiştir?', 'Çift pozlamayla portreye "hayalet" eklenerek', ['Işıkla boyayarak', 'Dijital kolajla', 'Elle çizilerek'], 'Mumler, ruhlarla görüşme yeteneği iddiasıyla çift pozlamayla hayalet imgeleri üretmiş, 1869\'da dolandırıcılıktan yargılanmış ve beraat etmiştir.'),
  ('Reuters\'in 2006\'da Lübnan bombardımanı fotoğraflarından birini ajans arşivinden çekmesinin nedeni nedir?', 'Fotoğrafçının dumanları dijital olarak kopyalayıp yoğunlaştırması', ['Fotoğrafın başka bir savaşa ait çıkması', 'Fotoğrafın telif ihlali içermesi', 'Fotoğrafın sansüre takılması'], 'Adnan Hajj\'ın Photoshop\'ta klonlayarak dumanı artırdığı fark edilince ajans bütün çalışmalarını yayından kaldırmıştır.'),
  ('Bernd ve Hilla Becher\'in su kuleleri, soğutma kuleleri ve yüksek fırınları aynı çerçeve ve ışıkla seri olarak çekmesi hangi yaklaşımı gösterir?', 'Endüstriyel yapıları tipoloji olarak karşılaştırmalı biçimde belgeleme', ['Yapıların renkli ve gösterişli yorumlanmasıyla reklam çekimleri hazırlama', 'Yapıları günün farklı saatlerinde dramatik ışıkla romantikleştirme', 'Her yapının bir ressam gibi, benzersiz bir kompozisyonla yorumlanması'], 'Çiftin kapalı, bulutlu havada, aynı uzaklık ve açıyla çektiği görüntüler "anonim heykeller" olarak sıralanıp biçim benzerlikleri ve farkları gösterilir.'),
  ('Becherlerin 1970\'te yayımlanan ve endüstri yapılarını "heykel" olarak niteleyen kitabının adı nedir?', 'Anonim Heykeller', ['Sanayi Katedralleri', 'Çelik Kentler', 'Kule Tipolojisi'], 'Çift, işlevsel yapıları, kimsenin tasarımcı olarak anılmadığı heykeller gibi ele alarak bakışı değiştirmiştir.'),
  ('Thomas Ruff\'ın 1980\'lerde sürdürdüğü "Portreler" dizisinin ayırt edici özelliği nedir?', 'Pasaport fotoğrafı gibi ifadesiz yüzlerin duvar boyutunda büyütülmesi', ['Modellerin dramatik ışıkla yorumlanması', 'Ünlü kişilerin sokakta gizlice çekilmesi', 'Yüzlerin elle boyanıp renklendirilmesi'], 'Ruff, duygusuz, düz bakışlı yüzleri devasa boyutta göstererek portre geleneğini ve fotoğrafın nesnelliğini sorgulamıştır.'),
  ('Andreas Gursky\'nin "99 Cent" (1999) fotoğrafında dijital müdahalenin başlıca işlevi nedir?', 'Rafları sonsuz tekrar eden bir desene dönüştürüp çarpıcı bir düzen kurmak', ['Mağazadaki kalabalığı tamamen silmek', 'Siyah beyaz bir etki yaratmak', 'Ürünlerin fiyatlarını değiştirmek'], 'Gursky, farklı çekimleri birleştirip düzenleyerek tüketim kültürünün bolluğunu soyut bir renk alanına çevirmiştir.'),
  ('Jeff Wall\'un fotoğraflarını aydınlatmalı kutular içinde sergilemesi neyi çağrıştırır?', 'Reklam panolarının cazibesini ve sinema ekranını', ['Müze duvarlarında klasik tabloların aydınlatılmasını', 'Gündoğumunun doğal ışığını', 'Basit bir aile albümünü'], 'Wall, arkadan aydınlatılmış saydam baskılarla fotoğrafa sinema ve reklam gibi kitlesel görsel kültürün gücünü kazandırmıştır.'),
  ('Jeff Wall\'un "Yıkılmış Oda" (1978) çalışması hangi sanat yapıtına göndermede bulunur?', 'Delacroix\'nın "Sardanapal\'ın Ölümü" tablosuna', ['Goya\'nın "Üçüncü Mayıs 1808" tablosuna', 'Courbet\'in "Atölye" tablosuna', 'Manet\'in "Olympia" tablosuna'], 'Wall, stüdyoda kurduğu darmadağın oda sahnesini, romantik tablodaki kaosla ilişkilendirmiştir.'),
  ('Wolfgang Tillmans\'ın 2000 yılında kazandığı ödül hangisidir?', 'Turner Ödülü', ['Pulitzer Ödülü', 'Hasselblad Ödülü', 'Prix Nadar'], 'Alman sanatçı, gündelik yaşam ve soyut baskılardan oluşan çalışmasıyla Turner Ödülü\'nü kazanan ilk fotoğrafçıdır.'),
  ('Francesca Woodman\'ın 1970\'lerde Providence\'ta çektiği fotoğraflar hangi özellikle akılda kalır?', 'Bulanık hareketlerle duvarda silinen, hayaletimsi kendi bedeni', ['Renkli moda çekimleri', 'Savaş muhabirliği', 'Karanlık manzara fotoğrafları'], 'Genç sanatçı uzun pozlarda kendi bedenini eski odalarda belirsizleştirerek yokluk ve kimlik üzerine etkileyici kareler üretmiştir.'),
  ('Barthes, "Camera Lucida"da yazdığı ve fotoğrafın doğasını anlatan "ça-a-été" (o vardı) ifadesiyle neyi vurgular?', 'Fotoğraftaki nesnenin, kameranın önünde gerçekten bulunmuş olduğunu', ['Fotoğrafın renkli olduğunu', 'Fotoğrafın sonradan işlenebildiğini', 'Görüntünün geleceği gösterdiğini'], 'Barthes\'a göre fotoğrafın ayırt edici özelliği, görüntülenen şeyin bir zamanlar gerçekten orada olduğunun kanıtını taşımasıdır.'),
  ('Charles Sanders Peirce\'in gösterge sınıflamasına göre fotoğrafı özellikle "indeks" olarak değerlendirmek neyi vurgular?', 'Görüntünün, ışığın nesneden fiziksel bir izi olarak oluşması', ['Görüntünün nesneye yalnızca benzemesi', 'Fotoğrafın simgesel dil kuralları taşıması', 'Fotoğrafın yalnızca gelenekle anlam kazanması ve yalnızca kültürel kurallara bağlı olması'], 'İndeks, nedensel bağla işaret ettiği şeyin izidir; ışığın gümüş tuzlarını etkilemesi bu bağı fotoğrafa özgü kılar.'),
  ('John Szarkowski\'nin 1966 tarihli "Fotoğrafçının Gözü" kitabı fotoğrafın hangi beş özelliğini inceler?', 'Şeyin kendisi, ayrıntı, çerçeve, zaman ve bakış açısı', ['Işık, renk, form, çizgi ve desen', 'Konu, teknik, mekân, zaman ve sanatçı ve sanatçı biyografisi anlayışı', 'Netlik, kontrast, ton, doku ve boyut'], 'Szarkowski, fotoğrafın resimden ayrılan biçimsel özelliklerini bu başlıklar altında örneklerle çözümlemiştir.'),
  ('Pascal Sébah\'ın 1873\'te Viyana Dünya Fuarı için hazırladığı albümün adı nedir?', 'Türkiye\'nin Halk Kıyafetleri', ['Boğaziçi Manzaraları', 'Padişahlar Albümü', 'Osmanlı Mimarisi'], 'Albüm, Osmanlı İmparatorluğu\'ndaki kıyafetleri ve meslek gruplarını stüdyoda kurulan sahnelerle sergileyen önemli bir kaynaktır.'),
  ('Beyoğlu\'nda stüdyosu bulunan ve Sultan Abdülaziz\'in fotoğrafçısı olarak bilinen Rum fotoğrafçı hangisidir?', 'Basile Kargopoulo', ['Guillaume Berggren', 'Vichen Abdullah', 'Robert Murray'], 'Kargopoulo, 1860\'larda Pera\'da stüdyosuyla saray çevresine portre ve kent görüntüleri satmıştır.'),
  ('Sultan II. Abdülhamid\'in 1893-94\'te ABD\'ye ve Britanya\'ya armağan ettiği fotoğraf albümlerinin amacı nedir?', 'Osmanlı\'nın modernleşmesini ve imparatorluğun ilerlemesini dış dünyaya göstermek', ['Savaşta ele geçirilen toprakları kanıtlamak', 'Padişahın aile hayatını tanıtmak', 'Ordu mensuplarının portrelerini sergilemek'], 'Albümler okul, kışla, fabrika ve köprü gibi görüntülerle Osmanlı\'nın çağdaş yüzünü anlatan bir imaj yönetimi çabasıdır.'),
  ('İsveçli Guillaume Berggren\'in 19. yüzyılda İstanbul\'da çektiği fotoğraflar ne tür bir malzemeye dönüşmüştür?', 'Turistlere satılan kent görüntüleri albümlerine', ['Resmî devlet arşivi belgelerine ve askerî haritalara ve devlet arşivlerine', 'Tıp kitaplarındaki çizimlere', 'Okul ders kitaplarına'], 'Berggren\'in albümin baskıları, Avrupa\'dan gelen seyyahlara satılan manzara albümleri için kaynak olmuştur.'),
  ('Ara Güler\'in 1961\'de katıldığı fotoğraf ajansı hangisidir?', 'Magnum', ['Gamma', 'Sygma', 'Black Star'], 'Güler, 1950\'lerde Yeni İstanbul gazetesi ve Hayat dergisinde çalıştıktan sonra Magnum\'a katılmıştır.'),
  ('Ara Güler\'in Doğu\'nun ve İstanbul\'un gündelik yaşamını siyah beyaz belgelemesi hangi anlayışla ilişkilendirilir?', 'Kent hafızasını koruyan belgesel ve insancıl bakış', ['Soyut ve deneysel biçimcilik ve gösterişli reklam estetiği', 'Moda ve reklam estetiği', 'Çağdaş kavramsal fotoğraf'], 'Güler\'in sokak, liman ve mahalle çekimleri, kaybolan bir İstanbul\'un görsel arşivi olarak değerlendirilir.'),
  ('Ara Güler\'in Picasso, Dalí ve Hitchcock gibi ünlüleri fotoğraflaması hangi işle ilgilidir?', 'Dergiler için portre çalışmasıyla', ['Askerlik görevinin parçası olarak', 'Yarışma gezisiyle', 'Bir film için set fotoğrafçılığıyla'], 'Fotoğrafçı, uluslararası dergiler için çektiği portrelerle ünlü sanatçı ve yazarların görüntülerini kaydetmiştir.'),
  ('Elliott Erwitt\'in 1959\'da Moskova\'da çektiği fotoğraf hangi olayı belgeler?', 'Nixon ile Hruşçov\'un "mutfak tartışması"nı', ['Kennedy\'nin ziyaretini', 'Berlin Duvarı\'nın yıkılışını ve ardından gelen basın toplantısını', 'Gagarin\'in uçuşunu'], 'Erwitt, bir ev mutfağında iki liderin tartışmasını yakalamış; bu görüntü Soğuk Savaş fotoğraflarının simgelerinden olmuştur.'),
  ('Eve Arnold\'un 1950\'lerde sahne arkasında yaklaşık on yıl boyunca fotoğrafladığı ünlü kişi kimdir?', 'Marilyn Monroe', ['Audrey Hepburn', 'Grace Kelly', 'Ingrid Bergman'], 'Magnum\'un önde gelen kadın üyelerinden Arnold, oyuncuyu doğal anlarında, sevecen bir yaklaşımla kaydetmiştir.'),
  ('Bruce Davidson\'ın 1966-68\'de çalıştığı "Doğu 100. Cadde" serisi hangi toplulukla ilgilidir?', 'New York\'un Doğu Harlem\'indeki yoksul sakinlerle', ['Brooklyn limanındaki işçilerle ve Brooklyn\'deki sanayi bölgesinde', 'Chicago çiftçileriyle', 'Los Angeles film yıldızlarıyla'], 'Davidson, tek bir sokakta ev ev dolaşarak orada yaşayanları yakın ve saygılı bir bakışla görüntülemiştir.'),
  ('René Burri\'nin 1963\'te Küba\'da çektiği portre kimi gösterir?', 'Che Guevara\'yı ağzında purosuyla', ['Fidel Castro\'yu konuşma yaparken', 'Hemingway\'i', 'Camilo Cienfuegos\'u'], 'İsviçreli Burri, Che\'yi sert bakışlı ve puro içerken yakalamış; bu portre dünyaca bilinir.'),
  ('Josef Koudelka\'nın 1975\'te yayımlanan "Çingeneler" kitabında konu aldığı topluluk hangi bölgededir?', 'Doğu Avrupa, özellikle Çekoslovakya ve Romanya', ['İspanya', 'Kuzey Afrika', 'İskandinavya'], 'Koudelka, yıllarca Roman topluluklarıyla birlikte yaşayarak yoğun ışık-gölgeli, dramatik siyah beyaz kareler çekmiştir.'),
  ('Evans\'ın 1938-41 arasında New York metrosunda saklı makineyle çektiği portrelerin kitabı hangisidir?', 'Çoğu Çağrılır', ['Metro Yaşamı ve Gizli Kameradaki Yüzler kitabı', 'Kent Yolcuları', 'Raylar'], 'Evans, mantosunun altına gizlediği makineyle yolcuların fark edilmeden ifadelerini kaydetmiş; kitabı 1966\'da yayımlanmıştır.'),
  ('Berenice Abbott, Eugène Atget\'ye fotoğraf tarihinde hangi katkıyı yapmıştır?', 'Arşivini satın alıp korumuş ve tanıtmıştır', ['Onunla ortak stüdyo kurmuştur', 'Onu Paris\'ten sürgün ettirmiştir ve sonra arşivini yok etmiştir', 'Onun makinesini devralmıştır'], 'Atget\'nin ölümünün ardından arşivini kurtaran Abbott, bu sayede fotoğrafçının ün kazanmasını sağlamıştır.'),
  ('Gardner Cowles\'un 1937\'de kurduğu ve LIFE ile rekabet eden resimli dergi hangisidir?', 'Look', ['Vogue', 'Picture Post', 'Vu'], 'Look, ucuz fiyatı ve fotoğraf ağırlıklı içeriğiyle LIFE\'a rakip olarak ABD\'de yayımlanmıştır.'),
  ('Işık kaynağı modelin tam önünde ve yukarıdadır; burnun altında küçük, simetrik bir gölge oluşur. Hollywood portrelerinde sık kullanılan bu düzen hangisidir?', 'Kelebek (Paramount) ışığı', ['Rembrandt ışığı: gölgedeki yanakta ters üçgen bırakan düzen', 'Bölünmüş ışık', 'Geniş ışık'], 'Ana ışığın yüzün ekseninde ve yüksekte durması, burun altında kelebek biçimli gölge bırakır; Hollywood güzellik portrelerinde sık kullanılmıştır.'),
  ('Bir portre fotoğrafçısı yüzü daha ince göstermek için yüzün kameraya yakın yanını gölgede bırakıp uzak yanını aydınlatıyor. Bu yönteme ne denir?', 'Kısa ışıklandırma', ['Geniş ışıklandırma', 'Düz ışıklandırma', 'Arka ışıklandırma'], 'Aydınlatılan taraf kameradan uzakta olunca yüz daha dar ve daha biçimli görünür; buna kısa ışıklandırma denir.'),
  ('Flaşın çok yakın çekimde fotoğrafı beyaza çevirmesinin temel nedeni nedir?', 'Işık şiddetinin konuya yaklaştıkça hızla artması', ['Flaşın renk sıcaklığının yükselmesi ve görüntünün mavileşmesi', 'Konunun ışığı emmesi', 'Makinenin çözünürlüğünün düşmesi'], 'Işık şiddeti uzaklığın karesiyle ters orantılı olduğundan çok yakın mesafede güç aşırı fazla olur ve parlak alan patlar.'),
  ('Gün ışığında portre çekerken çok sert öğle ışığının altında yüzün gözlerinin altı gölgede kalıyor. Hangisi bu sorunu çözmez?', 'Diyaframı daha da açmak', ['Yansıtıcı kullanmak', 'Dolgu flaşı vermek', 'Modeli gölge bir alana almak'], 'Diyaframı açmak pozlamayı etkiler ama gölge yönünü ve sertliğini değiştirmez; diğer seçenekler gölgeleri doldurur ya da ışığı yumuşatır.'),
  ('Bulutlu bir günde dışarıda çekilen fotoğrafta gökyüzünün tamamen beyaza dönüp ayrıntı kaybetmesini önlemek için hangi araç yararlıdır?', 'Dereceli nötr yoğunluk (GND) filtresi', ['Makro halka ile objektif ucunun uzatılması ve ışığın dağıtılması', 'Kızılötesi flaş', 'Polarizan olmayan kâğıt'], 'GND filtre, karanlık üst yarısıyla gökyüzünün ışığını azaltıp yeryüzüyle dengelenmesini sağlar.'),
  ('Karşıdan güneş alan bir portrede yüz karanlık kalıyor. Makinenin ölçüm modunu değiştirerek yüzü doğru pozlamak isteyen fotoğrafçı hangisini seçmelidir?', 'Spot ölçüm ve yüze yöneltmek', ['Matris ölçüm ve gökyüzünü kadraja almak', 'Merkez ağırlıklı ölçüm ve ufku ortaya koymak', 'Matris ölçümü yüzün gölgede kalması için açık bırakmak'], 'Spot ölçüm yalnızca küçük bir alanı okur; yüze yöneltilince ışık ölçer gökyüzünün parlaklığından etkilenmez.'),
  ('Gökyüzü ışıklı, öndeki figür karanlık bir gün batımı manzarasında siluet elde etmek için ölçümü nereden almak gerekir?', 'Parlak gökyüzünden', ['Karanlık figürün yüzünden', 'Zeminde bulunan taşlardan', 'Her yerden ortalama alarak'], 'Pozlama ışıklı gökyüzüne göre ayarlanınca figür koyu kalır; ölçüm gölgeli figüre yapılırsa gökyüzü patlar.'),
  ('Bir fotoğraf makinesinde 1/60 saniye süre veren bir sahneye, üç durak azaltan ND8 filtresi takılınca dengeli pozlama için enstantane yaklaşık nasıl olmalıdır?', '1/8 saniye', ['1/500 saniye, çünkü ışık artmıştır', '1/30 saniye, çünkü yalnızca bir durak azalmıştır', '1/15 saniye, çünkü iki durak azalmıştır'], 'Üç durak, ışığı sekizde bire düşürür; süre 8 kat uzar, yani 1/60\'ın yaklaşık sekiz katı, 1/8 saniye olur.'),
  ('Flaşın patlama süresi, deklanşörün açık kaldığı süreden çok kısa olduğunda, ortam ışığının pozlamasını değiştirip flaşla aydınlanan konunun pozlamasını neredeyse hiç etkilemeyen ayar hangisidir?', 'Enstantane', ['Flaş gücü', 'Flaş ile konu arasındaki mesafe', 'Flaşın yönü'], 'Flaşın verdiği ışık süre boyunca değil, kısa patlamayla alınır; ortam ışığı ise perdelerin açık kaldığı süreyle orantılı birikir.'),
  ('Aynı sahneyi f/4\'te 1/30 saniyede doğru pozlayan bir fotoğrafçı, f/1.4 diyaframlı bir objektife geçerse aynı ISO\'da doğru enstantane yaklaşık ne olur?', '1/250 saniye', ['1/60 saniye', '1/125 saniye, çünkü iki durak fark vardır', '1/1000 saniye, çünkü beş durak fark vardır'], 'f/4\'ten f/1.4\'e yaklaşık üç durak ışık artar; enstantane 8 kat kısalıp 1/30\'dan yaklaşık 1/250\'ye iner.'),
  ('Gün ışığına duyarlı bir film, tungsten ampulle aydınlanan bir odada kullanıldığında fotoğraflar nasıl çıkar ve düzeltmek için hangi filtre önerilir?', 'Turuncu ağırlıklı, mavi (80A) filtreyle', ['Mavi ağırlıklı, turuncu (85) dönüştürme filtresiyle', 'Yeşil ağırlıklı, macenta düzeltme filtresiyle', 'Mor ağırlıklı, sarı kontrast filtresiyle'], 'Gün ışığı filmi 5500 K\'ye göre dengelidir; 3200 K\'lik tungsten ışıkta turuncu tonlanır, mavi filtre bu farkı düzeltir.'),
  ('Geniş bir manzarada tek bir kırmızı şemsiyeli kişiyi küçük bir ölçekte bırakmak izleyicide hangi duyguyu çağrıştırabilir?', 'Yalnızlık ve doğa karşısında küçüklük', ['Kalabalık ve gürültü', 'Hızlı bir kent yaşamı', 'Soğuk bir stüdyo ortamı ve gürültülü bir kent yaşamı'], 'Kocaman ortam içinde küçük figür, ölçek farkıyla yalnızlık ve çevreye karşı kırılganlık duygusu verir.'),
  ('Odaklanıp kadrajı sonra değiştirmek (focus and recompose) çok geniş diyaframda yakın portrede neden hata doğurabilir?', 'Odak düzlemi küçük bir yay çizerek kaydığı için gözler odak dışı kalabilir', ['Çekim sırasında objektif uzar', 'Flaş çalışmaz', 'Işık ölçer bozulur'], 'Kamera ekseni dönerken odak mesafesi sabit kalır, kişinin gözü ise odak düzleminin önüne ya da arkasına kayabilir.'),
  ('Bir fotoğraf makinesinde odak halkası üzerindeki mesafe ölçeğini ve alan derinliği işaretlerini kullanarak ayarlanan manuel odak yöntemi hangi tekniğe imkân verir?', 'Hiperfokal mesafe odaklaması', ['Faz algılama', 'Odak yığınlama ve manuel odak kaydırma', 'Panning'], 'Ölçekteki işaretler, hangi mesafeler arasının net kalacağını gösterdiğinden fotoğrafçı hiperfokal odağı el ile ayarlayabilir.'),
  ('Gece gökyüzünü yıldızlar iz bırakmadan nokta gibi çekmek için tam kare ve 20 mm objektifte "500 kuralı"na göre en uzun enstantane yaklaşık kaç saniyedir?', '25 saniye', ['5 saniye', '100 saniye', '500 saniye'], 'Kural: 500 ÷ odak uzaklığı = 500 ÷ 20 = 25 saniye; daha uzun pozlarda yıldızlar çizgiye dönüşmeye başlar.'),
  ('Her 5 saniyede bir kare çekilen zaman atlamalı bir çekimden saniyede 24 kare ile 30 saniyelik bir video yapmak için toplam kaç dakika çekim yapmak gerekir?', '60 dakika', ['15 dakika', '30 dakika', '120 dakika'], '24 × 30 = 720 kare gerekir; 720 × 5 saniye = 3600 saniye, yani 60 dakika.'),
  ('Yağmurlu bir günde bir şelalenin akışını hem ipeksi hem de çevredeki yaprakları net göstermek için ne gereklidir?', 'Tripot, düşük ISO ve ND filtre ile birkaç saniyelik pozlama', ['Elde çekim ve 1/1000 saniye', 'Flaşla 1/200 saniye', 'Çok yüksek ISO ve açık diyafram'], 'Sabit makine ve uzun süre sayesinde su çizgi hâlinde akarken sabit nesneler keskin kalır; ND filtre aşırı pozlamayı önler.'),
  ('Bir spor fotoğrafçısı yarış arabasını takip ederken arka planı bulanık, aracı nispeten net çekmek istiyor. Hangi enstantane aralığı panning için daha uygun olur?', '1/60 ile 1/125 saniye arası', ['1/4000 saniye ve flaşın tam güçte kullanılması', '5 saniye', '30 saniye'], 'Çok kısa süreler hem arka planı hem aracı dondurur; çok uzun süreler ise aracı da bulandırır.'),
  ('Kalabalık bir meydanın birkaç saniyelik uzun pozlamayla çekilmesi fotoğrafın hangi yönünü öne çıkarır?', 'Hareketin izini ve zamanın geçişini', ['Anın tam olarak dondurulmasını', 'Renklerin aşırı doygunluğunu', 'Mimari ayrıntıların keskinliğini ve renk sıcaklığı'], 'Uzun pozlama zamanı tek karede biriktirir; hareketli insanlar silikleşirken sabit mekân keskin kalır.'),
  ('Binanın üst kısmının dar görünmesini (yakınsayan dikey çizgileri) makineyi yukarı eğmeden düzeltmek için görüntü makinesinde hangi hareket kullanılır?', 'Objektif tahtasını yukarı kaydırmak', ['Film düzlemini yana döndürmek', 'Objektifi bir yandan yana çevirmek (swing) ile eğik kadrajı düzeltmek', 'Körüğü kısaltmak'], 'Objektifi yukarı kaydırmak görüş alanını yükseltir; film düzlemi dikey kaldığından dikey çizgiler paralel kalır.'),
  ('Peyzaj fotoğrafçısı öndeki otlardan ufka kadar her şeyi net görmek için görüntü makinesinde objektifi öne doğru eğerse (tilt) hangi etki sağlanır?', 'Odak düzlemi zemine yatırılıp netlik derinliği artar', ['Görüntü ters döner', 'Diyafram otomatik kapanır', 'Flaş senkronu iyileşir'], 'Objektifin eğilmesi odak düzlemini döndürerek yere paralel hâle getirir ve dar diyaframa gerek bırakmaz.'),
  ('Basın fotoğrafçılarının 1930-50\'lerde sık kullandığı, büyük film ve flaşla çalışan makine hangisidir?', 'Speed Graphic', ['Rolleiflex', 'Leica', 'Polaroid'], 'Weegee gibi muhabirlerin kullandığı Speed Graphic, 4 × 5 inç film ve kablolu flaş ampulleriyle çalışırdı.'),
  ('İğne deliği (pinhole) kamerasında 0,5 mm çapındaki delik ile film arasındaki uzaklık 50 mm ise efektif diyafram yaklaşık kaçtır?', 'f/100', ['f/25', 'f/50', 'f/8'], 'Efektif diyafram = uzaklık ÷ delik çapı = 50 ÷ 0,5 = 100\'dür; bu yüzden pozlama çok uzun sürer.'),
  ('Güneşli bir gün f/8 ve 1/125 saniye ile pozlanan sahne için f/100\'lük bir iğne deliği kamerasında pozlama yaklaşık ne kadar olmalıdır?', '1,25 saniye', ['1/125 saniye', '12 saniye', '1/8 saniye'], '(100/8)² = 156 katı ışık kaybı vardır; 156 × (1/125) yaklaşık 1,25 saniyedir.'),
  ('William Willis\'in 1873\'te patentini aldığı yöntem hangisidir?', 'Platinotipi', ['Dagerreyotipi', 'Kalotipi', 'Autochrome'], 'Willis\'in platin tuzlarıyla çalışan bu yöntemi, gümüş baskıya göre çok daha kalıcı ve zengin tonlu baskılar verdi.'),
  ('Woodburytype (1864) yöntemi, kitaplara fotoğraf basmak için neye dayanır?', 'Pigmentli jelatinin kabartma kalıpla basılması', ['Gümüş tuzlarının kâğıda sürülmesi ve kâğıda ışıkla sabitlenmesi', 'Camın boyanması', 'Demir tuzlarının mavi pigmentleri'], 'Yöntemde jelatin kabartması metal bir kalıba basılır; bu kalıp mürekkeple basılarak fotografik tonlu baskılar elde edilir.'),
  ('Gün ışığında duyarlı kâğıdın üstüne yaprak ve çiçek yerleştirip saatlerce bekletilerek elde edilen kamerasız görüntü hangi adla anılır?', 'Lumen baskı', ['Rayograf', 'Solarizasyon', 'Kalotip'], 'Gümüş tuzlu kâğıt, ışığa doğrudan maruz kalarak kararır; nesnenin kapattığı yerler açık kalır.'),
  ('Büyütücü başlığı yükseltilip baskı genişliği iki katına çıkarıldığında, aynı yoğunlukta baskı için pozlama süresi yaklaşık kaç kat artar?', 'Dört kat', ['İki kat', 'Sekiz kat', 'Değişmez'], 'Işıklandırılan alan dört kat büyüdüğünden birim alana düşen ışık dörtte bire iner; süre yaklaşık dört katına çıkar.'),
  ('20 cm genişlikteki bir baskıda 10 saniyelik pozlama doğru sonuç veriyor. Aynı negatiften 40 cm genişlikte baskı için yaklaşık süre kaç saniyedir?', '40 saniye', ['20 saniye', '80 saniye', '10 saniye'], 'Genişlik iki katına çıkınca ışık alanı dört kat büyür; süre yaklaşık 4 × 10 = 40 saniye olur.'),
  ('Panokromatik siyah beyaz filmin banyo tankına yüklenirken tam karanlık gerekmesinin nedeni nedir?', 'Film bütün renklere duyarlıdır ve güvenli ışıkta bile pozlanır', ['Film yalnızca kırmızı ışıkta bozulur', 'Banyo kimyasalları ışıkta ısınır', 'Tank şeffaftır'], 'Panokromatik film mavi, yeşil, kırmızı bütün renklere duyarlı olduğundan hiçbir güvenli ışıkla çalışılamaz.'),
  ('Filmi ISO 400 yerine 1600 gibi çekip banyoyu normalden uzun tutmak hangi işlemle ilgilidir?', 'Push (zorlama) banyo', ['Pull (çekme) banyo', 'Çapraz banyo', 'Solarizasyon'], 'Zorlama banyo, düşük ışıkta daha yüksek hızlı çekime olanak verir, ama kontrastı ve taneyi artırır.'),
  ('Bir fotoğrafçı çok kontrastlı, parlak güneşli bir sahneyi çektiği filmi nasıl banyo ederse kontrastı yumuşatır?', 'Banyo süresini kısaltarak (pull)', ['Süreyi uzatarak (push)', 'Hiç banyo etmeyerek', 'Gün ışığında banyo ederek ve sonra yıkamadan bırakarak'], 'Kısa geliştirme parlak bölgelerin yoğunlaşmasını sınırlar; böylece kontrast azalır.'),
  ('Film banyosu sırasında tanktaki geliştiriciyi çok sık ve kuvvetli karıştırmak (agitasyon) ne tür bir sorun yaratabilir?', 'Kontrast ve yoğunluk artışı, kenar etkisi', ['Filmin silinmesi', 'Renk sapması', 'Görüntünün ters dönmesi ve baskı yüzeyinde parıldama'], 'Aşırı karıştırma, kenarlarda ve delikli kısımların yakınında yoğunluk farklılıkları ve kontrast artışı yapar.'),
  ('Bir negatifi 4000 dpi\'de taramak isteyen kişi için 36 mm genişlikteki karenin piksel genişliği yaklaşık kaç olur?', '5669', ['3600', '4000', '9000'], '36 mm = 1,417 inç; 1,417 × 4000 = yaklaşık 5669 pikseldir.'),
  ('Kodak DCS 100 (1991) fotoğraf tarihinde neden anılır?', 'Profesyoneller için satılan ilk ticari dijital SLR sistemlerinden olması', ['İlk renkli film olması', 'İlk telefon kamerası olması', 'İlk anında fotoğraf makinesi olması'], 'Nikon F3 gövdesine dayanan sistem, haber ajanslarına satılmış ve dijital muhabirliğin başlangıcını simgelemiştir.'),
  ('Casio QV-10\'u (1995) dönemin diğer dijital makinelerinden ayıran özellik nedir?', 'Arkasında çekim sonrası fotoğrafı gösteren renkli LCD ekranı olması', ['Film kullanması', 'Hiç pil gerektirmemesi', 'Yalnızca siyah beyaz çekmesi'], 'QV-10, çekilen kareyi hemen ekrandan görmeyi ilk kez tüketiciye sunan makinelerden biridir.'),
  ('Philippe Kahn\'ın 1997\'de yaptığı ve fotoğraf paylaşım tarihinde dönüm noktası sayılan olay nedir?', 'Kızının doğum anının cep telefonundan anında paylaşılması', ['İlk dijital panoramayı çekmesi', 'İlk fotoğraf yarışmasını düzenlemesi ve fotoğraf yazılımı kurmasını', 'Kodak\'ı satın alması'], 'Kahn, kamerayı telefona bağlayıp doğum hastanesinden fotoğrafı anında göndermiş, ilk telefon fotoğrafı paylaşımı sayılmıştır.'),
  ('Adobe Photoshop\'un 1990\'daki ilk sürümü hangi iki kardeş tarafından geliştirilmiştir?', 'Thomas ve John Knoll', ['Steve ve Chris Jobs', 'Bill ve Paul Allen', 'John ve Alan Turing'], 'Knoll kardeşler, piksel düzenlemeyi masaüstüne getirerek fotoğraf rötuşunun biçimini değiştirmiştir.'),
  ('Malick Sidibé\'nin 1960\'larda Bamako\'da çektiği fotoğraflar hangi konuyu anlatır?', 'Bağımsızlık sonrası gençlik kültürünü ve dans gecelerini', ['Savaş sahnelerini', 'Doğa manzaralarını', 'Sömürge yönetimini'], 'Mali\'nin 1960\'taki bağımsızlığı sonrası genç nesil, müzik, moda ve eğlence sahnelerinde canlı siyah beyaz karelerle görünür.'),
  ('Seydou Keïta\'nın Bamako\'daki stüdyosunda çektiği portrelerin ayırt edici özelliği nedir?', 'Desenli fonlar ve modellerin seçtiği aksesuarlarla özenli kurgu', ['Kırmızı göz etkisi', 'Çıplak flaşla çekilmiş anlık kareler', 'Aynı fon ve aynı poz'], 'Keïta, müşterilerin kendini istediği gibi göstermesine olanak veren fon ve aksesuarlarla zarif portreler üretmiştir.'),
  ('Dmitri Baltermants\'ın 1942 tarihli "Keder" fotoğrafında gökyüzü neden dramatik görünür?', 'Baskıda gökyüzü koyulaştırılarak dramatik hâle getirilmiştir', ['Film renkli çekildiği için', 'Güneşin batışı sırasında çekildiği için ve bulutların lens kusuru yüzünden', 'Sis nedeniyle'], 'Kerç\'te ölülerini arayan kadınları gösteren görüntüde karanlık gökyüzü, baskıda yapılan müdahaleyle yasın ağırlığını artırmıştır.'),
  ('Capa, Kertész, Brassaï ve Munkácsi\'nin ortak noktası nedir?', 'Macar doğumlu olup yurtdışında ün kazanmış fotoğrafçılar olmaları', ['Aynı ajansta çalışmaları', 'Aynı okulda okumaları', 'Aynı savaşta ölmeleri'], 'Dört isim de Macaristan\'dan ayrılıp Paris, Berlin ve New York\'ta modern fotoğrafın gelişmesine katkıda bulunmuştur.'),
  ('Germaine Krull\'un 1927\'de yayımlanan "Metal" portföyü nasıl bir konu işler?', 'Paris\'in demir yapılarını, köprülerini ve Eyfel\'i keskin açılarla', ['Portre stüdyosu çalışmalarını', 'Orman manzaralarını', 'Kıyı kasabalarını'], 'Krull, çelik konstrüksiyonun geometrisini aşağıdan ve yukarıdan çekilmiş kadrajlarla yeni nesnellik estetiğine taşımıştır.'),
  ('Lala Deen Dayal\'ı 19. yüzyıl Hint fotoğrafında anılır kılan nedir?', 'Hyderabad Nizamı ve Hindistan Genel Valisi\'nin saray fotoğrafçısı olması', ['İlk Hint renkli filmini üretmesi', 'Britanya\'da stüdyo kurması', 'İlk fotoğraf okulunu açması'], 'Dayal, 1880\'lerde hanedanlık portreleri ve mimari belgelerle ün kazanmış, Genel Vali\'nin resmî fotoğrafçısı unvanını almıştır.'),
  ('Raghu Rai\'nin 1984 Bhopal gaz kazasından sonra çektiği ve toprağa gömülen çocuk yüzünü gösteren fotoğraf neyin simgesi olmuştur?', 'Endüstriyel felaketin insani bedelinin', ['Savaşın kazananlarının ve gelecek nesillerin başarısının', 'Tarım devriminin', 'Kırsal göçün'], 'Fotoğraf, Union Carbide fabrikasından sızan zehirli gazın kurbanlarına dair uluslararası duyarlılığı artırmıştır.'),
  ('Li Zhensheng\'in Çin\'deki Kültür Devrimi\'nde çektiği fotoğrafların bir bölümünün onlarca yıl gizli kalmasının nedeni nedir?', 'Negatifleri yakalanma korkusuyla evinin döşemesi altına saklaması', ['Filmlerin banyo edilememesi', 'Fotoğrafların tamamen yok olması', 'Kendi isteğiyle yayımlamaması'], 'Muhabir, rejimin onaylamayacağı görüntüleri sakladı; fotoğraflar yıllar sonra yayımlanarak dönemin tanıklığı olmuştur.'),
  ('Mary Ellen Mark\'ın 1983 tarihli "Streetwise" çalışması kimleri konu alır?', 'Seattle\'da sokakta yaşayan gençleri', ['Hollywood yıldızlarını ve Los Angeles\'taki turistleri', 'Savaş mültecilerini', 'Çiftlik işçilerini'], 'Mark, ev kaçkını gençlerle uzun süre zaman geçirerek onların yaşamlarını yakın ve saygılı bir bakışla belgelemiştir.'),
  ('Larry Clark\'ın 1971 tarihli "Tulsa" kitabı fotoğraf tarihinde hangi nedenle önemlidir?', 'Kendi arkadaş çevresindeki uyuşturucu kullanımını içeriden anlatması', ['İlk renkli savaş fotoğrafı olması', 'Mimari fotoğrafı yenilemesi', 'Bilimsel fotoğrafçılığın başlangıcı olması'], 'Clark, çocukluk arkadaşlarının gençlik yıllarını yakın bir tanık gözüyle kaydederek otobiyografik fotoğraf geleneğine etki etmiştir.'),
  ('Aaron Siskind\'in fotoğraflarını soyut dışavurumcu ressamların çalışmalarına yaklaştıran özellik nedir?', 'Soyulmuş boya ve duvar yüzeyleri gibi sıradan nesneleri soyut biçimlere dönüştürmesi', ['Renk tuvaller kullanması', 'Klasik portre çekmesi', 'Savaş propagandası hazırlaması'], 'Siskind, yakın çekimle duvar lekelerini resimsel jestlere benzer işaretlere çevirerek Kline ve de Kooning\'in çevresinde yer almıştır.'),
  ('Harry Callahan\'ın eşi Eleanor\'u defalarca fotoğraflamasının fotoğraf tarihindeki önemi nedir?', 'Çoklu pozlama ve yalın kompozisyonla kişisel yaşamı sanata dönüştürmesi', ['Gazeteler için haber üretmesi', 'Moda çekimi yapması', 'Belgesel film çekmesi'], 'Callahan, Eleanor\'u şehir sokaklarında, doğada ve evde çekerek kişisel ilişkiyi şiirsel görüntüye çevirmiştir.'),
  ('Richard Prince\'in 1980\'lerde Marlboro reklamlarından kovboy imgelerini yeniden fotoğraflayıp kendi adıyla sergilemesi hangi sanat yaklaşımına örnektir?', 'Ödünç alma (appropriation)', ['Piktoryalizm', 'Foto muhabirliği', 'Doğrudan fotoğraf (belgesel yaklaşım)'], 'Prince, reklam imgesini yeniden fotoğraflayarak özgünlük ve yazarlık kavramlarını sorgulamıştır.'),
  ('Jaromír Funke\'nin Çek avangart fotoğrafındaki önemi nedir?', 'Geometrik ve soyut kompozisyonlarla kamerasız ve gerçeküstü denemeler yapması', ['Haber fotoğrafçılığına öncülük etmesi', 'Moda çekimleri yapması', 'Panoramik çekimler yapması'], 'Funke, "Zaman Sürüyor" gibi serilerle gerçeküstü ve soyut fotoğrafı Çekoslovakya\'da yaygınlaştırmıştır.'),
  ('Bilinen en eski sualtı fotoğrafı 1856\'da hangi İngiliz tarafından çekilmiştir?', 'William Thompson', ['Roger Fenton', 'Henry Fox Talbot', 'Julia Margaret Cameron'], 'Thompson, kutusunu Weymouth Körfezi\'nde suya indirerek ilk bilinen sualtı fotoğrafını çekmiştir.'),
  ('1908\'de Alman eczacı Julius Neubronner\'in geliştirdiği hava fotoğrafı yöntemi neydi?', 'Güvercinlere küçük kamera takmak', ['Balonla çekim', 'Uçakla çekim', 'Uçurtma ve ayna veya uçağa takılan film makinesi'], 'Neubronner hafif otomatik bir kamerayı güvercin göğsüne bağlayarak yolculuk sırasında zaman ayarlı kareler elde etmiştir.'),
  ('George Lawrence\'ın 1906\'da San Francisco depremi sonrasında kenti panoramik fotoğrafladığı yöntem hangisidir?', 'Uçurtmalarla yükseltilen kamera', ['Dev bir balon', 'Uçak', 'Yüksek bir bina veya yüksek bir binanın çatısı'], 'Lawrence, uçurtma halatına bağlı büyük bir panoramik makineyi yüksekten çekerek yıkılan kentin geniş görüntüsünü elde etmiştir.'),
  ('Tim Macmillan\'ın geliştirdiği, birçok kamera ile aynı anda çekim yapıp sahneyi dondurarak çevresinde dolaşma hissi veren tekniğin popüler adı nedir?', 'Zaman dilimi', ['Panning', 'Çoklu pozlama', 'Odak yığınlama'], 'Birçok kameradan çekilen kareler art arda gösterilince donmuş an etrafında hareketli bakış izlenimi doğar.'),
  ('Bir fotoğrafçı, bir böceğin gözünü büyük ayrıntıyla çekerken çok az alan derinliği buluyor. Bu durumda hangisi bu sorunu çözmenin yolu olarak seçilir?', 'Farklı odak mesafelerinde çok kare çekip birleştirmek', ['Ek flaşı kapatmak', 'Diyaframı açmak', 'Telekonvertör takmak'], 'Yakın çekimde alan derinliği milimetrelere iner; odak yığınlama farklı düzlemleri tek bir net görüntüde toplar.'),
  ('Gün ışığında panoramik çekim sırasında makinenin ışık ölçümü kilitlenmezse ne tür bir sorun yaşanabilir?', 'Karelerin birbirinden farklı parlaklıkta çıkıp birleşimde şerit görünmesi', ['Odak hatası', 'Renklerin tersine dönmesi', 'Flaşın patlaması'], 'Her kare farklı pozlanırsa birleştirilen panoramada koyu ve açık bantlar belirir.'),
  ('Bir müze, tarihi bir resmin renk doğruluğunu belgelemek için fotoğraflıyor. Resmin yanına konan renkli referans kartı ne işe yarar?', 'Baskı ve ekranda renkleri doğru ayarlamayı sağlar', ['Resmi korur', 'Işığı azaltır', 'Flaşı kontrol eder'], 'Renk kartı (örneğin 24 renkli hedef), çekimden sonra profil çıkarılarak renk doğruluğunu ölçmeye yarar.'),
  ('Belgesel fotoğrafçısı bir kişi yoksulluk içinde yaşıyorsa fotoğraf çekimi için önceden izin almasının asıl nedeni nedir?', 'Kişinin onurunu ve kendi hikâyesi üzerindeki hakkını korumak', ['Daha güzel kareler elde etmek', 'Işık düzenini kurmak', 'Telif hakkını artırmak'], 'Fotoğraf etiği, konunun saygınlığını ve rızasını göz önünde bulundurmayı gerektirir.'),
  ('Gün batımından sonra gökyüzünde yıldızların görünmeye başladığı ama ufukta hâlâ ışık kaldığı dönem astrofotoğrafçılar için hangi çekimlere uygundur?', 'Ufuk ışığı ve yıldızları aynı karede dengeleyen manzara çekimlerine', ['Yalnızca Ay çekimlerine', 'Yalnızca portre çekimlerine', 'Güneş çekimlerine'], 'Alacakaranlık, manzara ile yıldızlı gökyüzünün birlikte pozlanabildiği kısa bir zaman aralığı sunar.'),
  ('Baudelaire\'in 1859 Salon yazısında fotoğraf konusundaki temel görüşü nedir?', 'Fotoğraf, sanatın ve bilimin alçakgönüllü hizmetkârı olmalıdır', ['Fotoğraf resimden daha üstün bir sanattır ve fotoğrafın yalnızca portre için gerekli olduğu', 'Fotoğraf yalnızca portre için gereklidir', 'Fotoğraf tamamen yasaklanmalıdır'], 'Şair, fotoğrafın güzel sanatlara girmesini kabul etmez; belgelemeye hizmet eden yardımcı bir araç olarak görür.'),
  ('1862\'de Ingres ve bazı sanatçıların imzaladığı dilekçenin amacı neydi?', 'Fotoğrafın güzel sanat olarak tanınmasına karşı çıkmak', ['Fotoğrafçılara devlet maaşı bağlamak ve devlet destekleri sağlamak', 'Dagerreyotipi yasaklamak', 'Fotoğrafa vergi koymak'], 'Dilekçe, fotoğrafın sanat sergilerinde ve sanat korumalarında yer almamasını istemiş, sanatçılarla fotoğrafçılar arasındaki gerginliği yansıtmıştır.'),
  ('Eugène Durieu\'nun 1853-54\'te çektiği çıplak model fotoğrafları kimin için hazırlanmıştır?', 'Eugène Delacroix ve diğer ressamlar için çalışma gereci olarak', ['Mahkeme dosyaları için', 'Tıp kitapları için', 'Dergi kapağı için'], 'Delacroix, fotoğrafları çizim ve resimlerinde bedeni incelemek için kullanmış; bu durum fotoğrafın ressamların çalışma pratiğine girişini gösterir.'),
  ('Edgar Degas\'nın 1890\'larda lamba ışığıyla çektiği ve arkadaşlarını portre olarak kaydettiği fotoğraflar onun hakkında ne gösterir?', 'Fotoğrafı yalnızca ön çalışma değil, bağımsız bir deney alanı olarak da gördüğünü', ['Fotoğrafı reddettiğini', 'Yalnızca peyzaj sevdiğini', 'Renklerden kaçındığını'], 'Degas, uzun pozlu gece çekimleriyle kendi kompozisyon arayışını sürdürmüş ve fotoğrafı da ciddiye almıştır.'),
  ('ABD\'de fotoğrafı çekilen ilk başkanlardan sayılan John Quincy Adams hangi yöntemle fotoğraflanmıştır?', 'Dagerreyotip', ['Kalotip', 'Kolodyon', 'Autochrome'], '1843\'te çekilen bu dagerreyotip, bilinen en eski başkan fotoğraflarındandır.'),
  ('Berkowski\'nin 1851\'de Königsberg\'de çektiği dagerreyotip neden önemlidir?', 'Güneş tutulmasının bilinen ilk başarılı fotoğraflarından olması', ['İlk renkli fotoğraf olması', 'İlk savaş fotoğrafı olması', 'İlk portre olması'], 'Tam tutulma sırasında çekilen görüntü, güneşin tacını ve ışık halelerini kalıcı olarak kaydetmiştir.'),
  ('Odak uzaklığı 50 mm olan bir mercekle 2 m uzaktaki bir konu odaklanırsa görüntü mercekten yaklaşık kaç mm uzakta oluşur?', 'Yaklaşık 51,3 mm', ['Yaklaşık 50 mm', 'Yaklaşık 100 mm', 'Yaklaşık 25 mm'], 'İnce mercek denklemi 1/f = 1/u + 1/v ile v = 1/(1/50 − 1/2000) yaklaşık 51,3 mm bulunur.'),
  ('Tam kare makinede 24 mm objektif f/8\'e kapatılıp 0,03 mm bulanıklık çemberiyle hiperfokal uzaklık yaklaşık kaç metredir?', 'Yaklaşık 2,4 m', ['Yaklaşık 24 m', 'Yaklaşık 0,24 m', 'Yaklaşık 8 m'], 'H = f²/(N·c) + f = 576/(8×0,03) + 24 yaklaşık 2424 mm, yani 2,4 metredir.'),
  ('Talbot\'un 1841\'de kalotip için aldığı patent İngiltere\'de fotoğrafın gelişimini nasıl etkilemiştir?', 'Yöntemin yaygınlaşmasını kısıtlamıştır, bu da patentsiz yöntemlere yönelmeyi artırmıştır', ['Kalotipin Avrupa\'nın her yerinde bedavaya kullanılmasını sağlamıştır ve yalnızca sınırlı bir bölgeyle sınırlı kalmıştır', 'Dagerreyotipin İngiltere\'de yasaklanmasına yol açmıştır', 'Fotoğraf makinesi üretimini devletin tekeline vermiştir'], 'Talbot\'un lisans uygulaması amatörleri ve stüdyoları sıkıştırdığı için kolodyon gibi serbest yöntemler daha çok tutulmuştur.'),
  ('Ansel Adams\'ın 1943\'te Manzanar\'da çektiği fotoğrafları içeren kitabın adı nedir?', 'Özgür ve Eşit Doğmuş', ['Sessiz Vadi', 'Gizli Kamp', 'Hepimiz Amerikalıyız ve Savaş Yıllarının Anıları'], 'Adams, kampın içindeki insanları yaşam enerjisiyle, saygılı bir üslupla göstermiş; kitap 1944\'te yayımlanmıştır.'),
  ('André Bazin\'in "Fotoğrafik İmgenin Ontolojisi" yazısında fotoğrafı hangi kültürel eğilimle ilişkilendirdiği söylenir?', 'Zamanı dondurup bedeni koruma isteğiyle', ['Renk sevgisiyle', 'Teknolojiye karşı çıkışla', 'Kâğıt kültürüyle'], 'Bazin, ölümü yenmek için bedeni korumaya çalışan eski gelenekle fotoğrafın ilişkisini kurar.'),
  ('Allan Sekula\'nın "Beden ve Arşiv" (1986) makalesi fotoğrafın hangi iki işlevini ayırarak inceler?', 'Onurlandırıcı portre ile baskıcı (polis fişleme) kullanımı', ['Sanat ve reklam', 'Renkli ve siyah beyaz', 'Amatör ve profesyonel'], 'Sekula, 19. yüzyılda burjuva portresi ile suçlu fotoğrafçılığını karşıt kutuplar olarak okur.'),
  ('Szarkowski\'nin 1978 tarihli "Aynalar ve Pencereler" sergisi hangi ayrımı öne çıkarır?', 'Kendini ifade eden fotoğraf ile dünyaya açılan pencere gibi belgesel fotoğraf', ['Renkli ve siyah beyaz', 'Portre ve manzara', 'Haber ve reklam'], 'Szarkowski, fotoğrafçıların bir yanıyla kendi iç dünyasını yansıttığı, bir yanıyla dünyayı gösterdiği ikiliği tartışır.'),
  ('Fransa\'da 1970\'te başlayan ve bugün hâlâ yaz aylarında gerçekleşen uluslararası fotoğraf festivali hangisidir?', 'Arles Fotoğraf Buluşmaları', ['Perpignan Visa pour l\'Image', 'Cannes Festivali', 'Photokina'], 'Arles\'taki bu festival, tarihî mekânlarda yapılan sergileriyle fotoğraf sanatının önemli buluşmalarındandır.'),
  ('1950\'den beri Köln\'de düzenlenen büyük fotoğraf ve görüntüleme fuarı hangisidir?', 'Photokina', ['Paris Photo', 'Visa pour l\'Image', 'Magnum Buluşması'], 'Photokina, fotoğraf endüstrisinin yeni ürünlerinin tanıtıldığı dünyanın en büyük fuarlarındandır.'),
  ('George Eastman Evi (Müzesi) hangi şehirdedir?', 'Rochester', ['Boston', 'Chicago', 'Philadelphia'], 'Eastman\'ın evinde kurulan müze, dünyanın en önemli fotoğraf ve film koleksiyonlarından birine sahiptir.'),
  ('Perpignan\'daki "Visa pour l\'Image" festivali neye odaklanır?', 'Foto muhabirliği', ['Moda fotoğrafı', 'Doğa fotoğrafı', 'Stüdyo reklam fotoğrafı'], 'Festival, 1989\'dan beri foto muhabirliği ve haber fotoğrafçılığı sergilerini bir araya getirir.'),
  ('Joseph Petzval\'in 1840\'ta tasarladığı objektifin fotoğraf tarihindeki önemi nedir?', 'Portre çekimini dakikalara varan pozlamadan saniyelere indirmesi', ['İlk zum objektifi olması', 'İlk balık gözü olması', 'İlk makro objektif olması'], 'Petzval portre objektifi, dagerreyotip portrelerde çok daha ışıklı bir açıklık sağlayarak pozlama süresini kısaltmıştır.'),
  ('Paul Rudolph\'un 1902\'de tasarladığı ve hâlâ kullanılan dört elemanlı mercek tipine ne denir?', 'Tessar', ['Planar', 'Sonnar', 'Elmar'], 'Zeiss\'ın Tessar tasarımı, keskinliği ve basitliğiyle yüzyıl boyunca makinelerde kullanılmıştır.'),
  ('Foto muhabirliği ajansı Black Star 1935\'te hangi kentte ve kimler tarafından kurulmuştur?', 'New York\'ta Almanya\'dan gelen göçmenler tarafından', ['Londra\'da İngiliz fotoğrafçılar tarafından ve yalnızca portre odaklı', 'Paris\'te Fransız ressamlar tarafından', 'Moskova\'da Sovyet gazeteciler tarafından'], 'Hitler döneminde Almanya\'dan kaçan yayıncılar, Avrupa foto muhabirlerinin işlerini Amerikan dergilerine satmak için ajans kurmuştur.'),
  ('Bir koleksiyoner aynı negatiften 1930\'larda yapılmış "vintage" bir baskı ile 1980\'lerde yapılmış bir baskıyı karşılaştırıyor. "Vintage" baskı terimi neyi gösterir?', 'Çekimden kısa süre sonra, fotoğrafçının kendi yaptığı dönem baskısını', ['En yeni baskı yöntemini', 'Dijital kopyayı', 'Müzeye bağışlanan baskıyı'], 'Vintage baskı, negatifin çekildiği döneme yakın zamanda üretildiğinden daha değerli sayılır.'),
  ('Susan Sontag, fotoğrafı sık sık "ölüm" ve "zamanın geçişi" ile ilişkilendirir. Bu görüş fotoğrafın hangi özelliğine dayanır?', 'Her fotoğrafın anı dondurup sonrasını geçmişe taşıması', ['Renklerin soluk olması', 'Kameranın pahalı olması', 'Baskı kâğıdının sararması'], 'Her kare, şimdinin geçmiş olduğunu ve görüntüdekilerin ölümlü olduğunu hatırlatır.'),
  ('Fotoğrafın "indeks" özelliği, bir fotoğrafın mahkemede delil olarak kabul edilmesini hangi yönden destekler?', 'Görüntünün nesneyle fiziksel bir bağı olduğu varsayımı', ['Fotoğrafın renkli olması', 'Kamera markası', 'Baskı kâğıdının türü'], 'Işığın nesneden yansıyıp sensöre gelmesi, görüntünün olayla nedensel bir bağı olduğu inancını güçlendirir; dijital manipülasyon bu güveni zayıflatmıştır.'),
];
